"tenantId\":{\"pattern\":\"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$\",\"type\":\"string\"},\"tokenScope\":{\"description\":\"The `scope` requested at the token endpoint, such as `https://storage.azure.com/.default`.\",\"maxLength\":512,\"pattern\":\"^[A-Za-z0-9:/._-]+$\",\"type\":\"string\"}},\"required\":[\"model\",\"tenantId\",\"clientId\",\"tokenScope\"],\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"Egress: the host of `tokenEndpoint`, and nothing else.\",\"properties\":{\"audience\":{\"description\":\"The assertion's `aud`. Absent means `tokenEndpoint`.\",\"maxLength\":2048,\"pattern\":\"^[!-~]+$\",\"type\":\"string\"},\"clientId\":{\"maxLength\":512,\"minLength\":1,\"pattern\":\"^[!-~]+$\",\"type\":\"string\"},\"model\":{\"const\":\"oauth2-private-key-jwt\",\"type\":\"string\"},\"scopes\":{\"description\":\"The scopes a binding may request, the ceiling for every issuance.\",\"items\":{\"maxLength\":256,\"pattern\":\"^[!#-\\\\[\\\\]-~]+$\",\"type\":\"string\"},\"maxItems\":64,\"type\":\"array\",\"uniqueItems\":true},\"signingAlgorithm\":{\"enum\":[\"ES256\",\"RS256\"],\"type\":\"string\"},\"tokenEndpoint\":{\"$ref\":\"#/$defs/ProviderHttpsUrl\"}},\"required\":[\"model\",\"tokenEndpoint\",\"clientId\"],\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"Issuance needs no egress: presigning is a computation inside the custodian, and the consumer uses the URL itself. The probe connects to the host of `endpoint`, which `egressHosts` therefore lists.\",\"properties\":{\"accessKeyId\":{\"description\":\"The access key's identifier. Not a secret: it appears in every presigned URL. The secret half is set with external/accounts/secret/set and never returned.\",\"maxLength\":128,\"pattern\":\"^[A-Za-z0-9]+$\",\"type\":\"string\"},\"bucket\":{\"$ref\":\"#/$defs/ProviderBucketName\"},\"endpoint\":{\"$ref\":\"#/$defs/ProviderHttpsUrl\"},\"model\":{\"const\":\"s3-static-presign\",\"type\":\"string\"},\"pathStyle\":{\"description\":\"Address the bucket in the path rather than the host name, as MinIO usually needs.\",\"type\":\"boolean\"},\"probePrefix\":{\"$ref\":\"#/$defs/ProviderObjectPrefix\",\"description\":\"Where external/accounts/probe writes its canary when no binding names a narrower prefix. Lets a new account be probed before anything is bound to it. Absent, a probe of an account with no bindings stops after `exchange` and reports `complete: false`.\"},\"region\":{\"description\":\"The SigV4 signing region; `auto` for Cloudflare R2.\",\"maxLength\":64,\"pattern\":\"^[a-z0-9-]+$\",\"type\":\"string\"}},\"required\":[\"model\",\"endpoint\",\"region\",\"bucket\",\"accessKeyId\"],\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"No egress: the custodian signs and the consumer submits the transaction. The allow-list, the gas caps and the coin caps are the account's whole authority; a transaction outside them is refused before anything is signed.\",\"properties\":{\"allowedCalls\":{\"description\":\"Every MoveCall command in a signed transaction must name one of these. For Walrus storage: the system package's `register_blob`, `certify_blob`, `extend_blob` and `delete_blob`, and the coin calls needed to pay for them.\",\"items\":{\"$ref\":\"#/$defs/SuiMoveCall\"},\"maxItems\":32,\"minItems\":1,\"type\":\"array\"},\"allowedObjects\":{\"description\":\"Shared objects a transaction may take as input, such as the Walrus system and staking objects. Absent means any object the allowed calls accept.\",\"items\":{\"pattern\":\"^0x[0-9a-f]{64}$\",\"type\":\"string\"},\"maxItems\":32,\"type\":\"array\"},\"maxCoinOutPerTx\":{\"description\":\"Per coin type, the most a single transaction may spend or transfer out of the account's address, in the coin's smallest unit. A coin type not listed may not leave the address at all.\",\"items\":{\"additionalProperties\":false,\"properties\":{\"amount\":{\"minimum\":0,\"type\":\"integer\"},\"coinType\":{\"maxLength\":512,\"pattern\":\"^0x[0-9a-f]{1,64}::[A-Za-z0-9_]+::[A-Za-z0-9_]+$\",\"type\":\"string\"}},\"required\":[\"coinType\",\"amount\"],\"type\":\"object\"},\"maxItems\":8,\"type\":\"array\"},\"maxGasBudgetMist\":{\"description\":\"The largest gas budget one transaction may declare.\",\"minimum\":1,\"type\":\"integer\"},\"maxGasPerDayMist\":{\"description\":\"The total gas budget signed per rolling 24 hours.\",\"minimum\":1,\"type\":\"integer\"},\"model\":{\"const\":\"sui-signer\",\"type\":\"string\"},\"network\":{\"enum\":[\"mainnet\",\"testnet\",\"devnet\"],\"type\":\"string\"}},\"required\":[\"model\",\"network\",\"allowedCalls\",\"maxGasBudgetMist\",\"maxGasPerDayMist\"],\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"Egress: the host of `baseUrl`. The secret is set with external/accounts/secret/set and used only inside the custodian by `driver`; a provider reachable only by handing the consumer the raw key is not supported.\",\"properties\":{\"baseUrl\":{\"$ref\":\"#/$defs/ProviderHttpsUrl\"},\"driver\":{\"description\":\"The custodian's driver that uses the secret: performs a login or token exchange and returns a short-lived result. A custodian refuses a driver it does not implement.\",\"maxLength\":64,\"pattern\":\"^[a-z0-9][a-z0-9-]*$\",\"type\":\"string\"},\"model\":{\"const\":\"static-secret\",\"type\":\"string\"}},\"required\":[\"model\",\"driver\",\"baseUrl\"],\"type\":\"object\"}],\"title\":\"AccountSettings\"}"
