macro_rules! d_AclEntry_84c82c8d {
    () => {
        "\"AclEntry\":{\"additionalProperties\":false,\"properties\":{\"allowedKeys\":{\"description\":\"Key identifiers this subject may invoke the maintainer's signing oracle on. INTERSECTS WITH `scopes` — it can only narrow, never widen: a key named here that lies outside the entry's scopes remains unreachable, exactly as if it were not named. ABSENT means every key within the entry's scopes (the behaviour of entries that pre-date this member); explicit `null` is equivalent to absent, and producers SHOULD omit the member instead. PRESENT-BUT-EMPTY means authorized on NO keys — the opposite of absent, and deliberately so: emptiness is never a wildcard (CONVENTIONS.md §5). A consumer MUST preserve and enforce the absent-vs-empty distinction end to end; collapsing the two (e.g. by testing emptiness alone) re-creates the empty-means-unrestricted class of privilege-escalation defect this family's conventions exist to prevent.\",\"items\":{\"type\":\"string\"},\"type\":[\"array\",\"null\"]},\"approve\":{\"additionalProperties\":false,\"description\":\"Approve-authority: what this subject may **confer on others** by ratifying an approval, as distinct from `scopes`, which is what it may **exercise itself**. The two axes are independent, and that independence is the point — it is what lets a maintainer configure a least-privilege approver who can authorize an operation in a scope it has no authority to perform.\\n\\nOMISSION MEANS NOTHING IS CONFERRED. An absent `approve`, an absent `all`, and an empty `scopes` are all equivalent to \\\"this subject may ratify nothing\\\". A consumer that does not implement this member therefore confers less than the producer intended rather than more, which is the direction a missed member has to fail in.\\n\\nA subject with approve-authority is NOT thereby authorized to act. Consumers MUST resolve the two axes separately: reading `approve` to answer \\\"may this party ratify X\\\" and `scopes` to answer \\\"may this party do X\\\". Collapsing them grants an approver the ability to perform what it was only meant to sign off on.\",\"properties\":{\"all\":{\"default\":false,\"description\":\"The subject may confer ANY scope. Takes precedence over `scopes`, which a consumer MUST ignore when this is true. Absent or false → only the scopes listed below, if any.\",\"type\":\"boolean\"},\"scopes\":{\"description\":\"Opaque scope identifiers this subject may confer, drawn from the same vocabulary as the entry's own `scopes`. Where a maintainer's scopes are hierarchical, conferring a scope confers its descendants — the same containment rule the maintainer already applies to `scopes`, so the two axes cannot disagree about what a scope means. An empty array confers nothing; it is not a wildcard.\",\"items\":{\"type\":\"string\"},\"type\":\"array\"}},\"type\":\"object\"},\"createdAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"createdBy\":{\"description\":\"VID of the party that originally added this entry.\",\"type\":\"string\"},\"expiresAt\":{\"description\":\"Optional time after which the entry is no longer effective.\",\"format\":\"date-time\",\"type\":\"string\"},\"ext\":{\"$ref\":\"#/$defs/Ext\",\"description\":\"Ecosystem-defined extension members per SPEC.md §4.5.1. Reverse-DNS-namespaced; consumers MUST ignore unrecognized namespaces.\"},\"label\":{\"description\":\"Optional human-readable label.\",\"maxLength\":256,\"type\":\"string\"},\"role\":{\"description\":\"Opaque role identifier interpreted by the ACL maintainer.\",\"type\":\"string\"},\"scopes\":{\"description\":\"Opaque scope identifiers (e.g. contexts, domains, resource prefixes).\",\"items\":{\"type\":\"string\"},\"type\":\"array\"},\"stepUp\":{\"additionalProperties\":false,\"description\":\"Per-entry authentication step-up configuration, consumed by the ACL maintainer when it gates an operation behind a step-up (see auth/step-up/policy/0.1). ADDITIVE-ONLY: a per-entry setting MAY raise the assurance required of this subject above the maintainer's system-wide floor, but MUST NOT lower it. The maintainer resolves the effective requirement as the strictest of (system floor, this entry).\",\"properties\":{\"approver\":{\"description\":\"VID authorized to ratify step-up for this subject — the `recipient` the maintainer addresses an auth/step-up/approve-request to (e.g. the holder's mobile authenticator or browser companion). Absent → the subject is its own approver (mode `self`) when it holds a usable authenticator; if neither an `approver` nor a self authenticator exists, no step-up method is available for this subject and the maintainer's fail-closed rule applies.\",\"type\":\"string\"},\"require\":{\"description\":\"Minimum step-up mode this subject MUST satisfy for gated operations, raising the system floor. `self` = the subject re-authenticates its own session; `delegated` = a separate `approver` MUST ratify. Omitted → the system floor applies unchanged. A value weaker than the resolved floor is ignored (additive-only).\",\"enum\":[\"self\",\"delegated\"],\"type\":\"string\"}},\"type\":\"object\"},\"subject\":{\"description\":\"VID of the party in the ACL. Compared by exact string equality (SPEC.md §4.8); producers SHOULD emit canonical form.\",\"type\":\"string\"},\"updatedAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"updatedBy\":{\"description\":\"VID of the party that last modified this entry.\",\"type\":\"string\"}},\"required\":[\"subject\",\"role\"],\"title\":\"AclEntry\",\"type\":\"object\"}"
    };
}
pub(crate) use d_AclEntry_84c82c8d;

macro_rules! d_ActivityItem_2ca777f2 {
    () => {
        "\"ActivityItem\":{\"additionalProperties\":false,\"description\":\"One thing that happened in a namespace.\",\"properties\":{\"action\":{\"description\":\"What happened: `gitNs.right.granted`, `gitNs.repo.renamed`, `gitNs.drift.reported`, `gitNs.job.createRepo`, and so on. Not a closed enumeration — a VTC MAY add its own dot-separated `gitNs.*` actions, and a consumer MUST treat one it does not recognise as an opaque activity item rather than failing to parse it.\",\"maxLength\":128,\"minLength\":1,\"pattern\":\"^[a-zA-Z][a-zA-Z0-9]*(\\\\.[a-zA-Z][a-zA-Z0-9]*)*$\",\"type\":\"string\"},\"actor\":{\"$ref\":\"#/$defs/Did\",\"description\":\"Who acted, for an audit item. Absent when a right-to-be-forgotten erasure has removed it from the audit row, and always absent for a job item, which has no actor of its own.\"},\"at\":{\"description\":\"When it happened: the audit row's timestamp, or the job's acceptance time (its creation time if never accepted).\",\"format\":\"date-time\",\"type\":\"string\"},\"detail\":{\"description\":\"A machine-readable qualifier: `departed` on a departure-triggered change, the old name on a rename, a job's queue state, a drift count. A producer MUST NOT put free-form or personal prose here beyond what the qualifier itself names.\",\"maxLength\":1024,\"type\":\"string\"},\"namespace\":{\"$ref\":\"#/$defs/NamespaceId\",\"description\":\"The namespace the item belongs to. Absent only for a community-wide audit row from before any namespace was unbound (visible to a community administrator with no `namespace` filter only).\"},\"resource\":{\"$ref\":\"#/$defs/Resource\",\"description\":\"The resource the item concerns, where it names one.\"},\"right\":{\"$ref\":\"#/$defs/Right\",\"description\":\"The right a rights-change item concerns. Absent for a drift report or a job item.\"},\"source\":{\"$ref\":\"#/$defs/Source\",\"description\":\"Where the item came from: an audit row or a bridge job.\"},\"subject\":{\"$ref\":\"#/$defs/Did\",\"description\":\"Whose right it was, for a rights-change audit item. Absent likewise on erasure, and always absent for a job item.\"}},\"required\":[\"at\",\"action\",\"source\"],\"title\":\"ActivityItem\",\"type\":\"object\"}"
    };
}
pub(crate) use d_ActivityItem_2ca777f2;

macro_rules! d_AdminRightRow_e929be24 {
    () => {
        "\"AdminRightRow\":{\"additionalProperties\":false,\"description\":\"One right as the administrator's rights console shows it: a recorded `RightRecord` restated with the membership facts an administrator needs (`subjectMember`, `granterDeparted`), or a role-derived grant that carries no record. `git-ns/right/list` and `git-ns/right/issued-by-departed` are its only producers.\",\"properties\":{\"breakGlass\":{\"$ref\":\"#/$defs/BreakGlass\",\"description\":\"Present exactly when `origin` is `recorded` and the record carries `breakGlass` — see `RightRecord.breakGlass`. Absent for a role-derived grant, which cannot be self-granted through break-glass.\"},\"expiresAt\":{\"description\":\"When the right lapses. Absent: no expiry, or `origin` is `roleDerived` (a role-derived grant never expires on its own — it is withdrawn by editing `[hooks.git-trust] grant_on_role`).\",\"format\":\"date-time\",\"type\":\"string\"},\"grantedAt\":{\"description\":\"Present exactly when `origin` is `recorded`.\",\"format\":\"date-time\",\"type\":\"string\"},\"grantedBy\":{\"$ref\":\"#/$defs/Did\",\"description\":\"Who caused the right (see `RightRecord.grantedBy`). Present exactly when `origin` is `recorded`; a role-derived grant is published by the hook relay from configuration, not by an actor.\"},\"granterDeparted\":{\"description\":\"Whether `grantedBy` was a member at the time of the grant and has since left. Always `false` when `origin` is `roleDerived`, or when the record's granter was never itself a member (the VTC's own DID, for a right it derives from configuration).\",\"type\":\"boolean\"},\"origin\":{\"$ref\":\"#/$defs/RightOrigin\"},\"reason\":{\"description\":\"The granter's free-text reason, restated from the `RightRecord`. Absent when `origin` is `roleDerived`, or the record carries none.\",\"maxLength\":1024,\"type\":\"string\"},\"resource\":{\"$ref\":\"#/$defs/Resource\"},\"right\":{\"$ref\":\"#/$defs/Right\"},\"subject\":{\"$ref\":\"#/$defs/Did\",\"description\":\"Who holds the right.\"},\"subjectMember\":{\"description\":\"Whether `subject` is a current member of the community. `false` marks a right held by someone who has since left, or by an external signer the community never enrolled.\",\"type\":\"boolean\"}},\"required\":[\"subject\",\"right\",\"resource\",\"origin\",\"subjectMember\",\"granterDeparted\"],\"title\":\"AdminRightRow\",\"type\":\"object\"}"
    };
}
