macro_rules! d_BlobManifest_d794e44a {
    () => {
        "\"BlobManifest\":{\"additionalProperties\":false,\"description\":\"The ciphertext manifest of one blob, committed by the uploader before any byte moves. Its digest is the BlobRef. Every chunk is checked against `chunks.chunkDigests` on arrival and the reassembled blob against `digest`, so a host can neither accept nor serve bytes the uploader did not commit to. The manifest also appears, by its BlobRef, inside the sealed FileManifest the author signs; a reader who opens the record therefore knows which ciphertext its author meant, and a host cannot substitute a different blob under the same record.\\n\\nConsistency rules JSON Schema cannot state: `chunks.chunkCount` MUST equal ceil(size / chunks.chunkSize), and `chunks.chunkDigests` MUST have exactly `chunkCount` items. A party receiving a manifest violating either MUST refuse it.\\n\\nEach transfer chunk is exactly one sealed STREAM segment (see FileManifest): every chunk but the last is `chunkSize` bytes, and `chunkSize` is the plaintext segment size plus the 16-byte AEAD tag. The 262144-byte ceiling of ChunkSize therefore puts the largest plaintext segment at 262128 bytes, and the 4096-chunk ceiling of ChunkCount puts the largest blob at 1 GiB of ciphertext.\",\"properties\":{\"chunks\":{\"$ref\":\"#/$defs/ChunkManifest\"},\"digest\":{\"$ref\":\"#/$defs/DigestMultibase\",\"description\":\"Digest of the whole ciphertext, over its bytes. Checked after reassembly, so a correct set of chunks in the wrong order is still caught.\"},\"size\":{\"$ref\":\"#/$defs/ExpectedSizeBytes\",\"description\":\"Ciphertext bytes, padding included. What the host stores, and what every limit and usage figure is stated in.\"}},\"required\":[\"size\",\"chunks\",\"digest\"],\"title\":\"BlobManifest\",\"type\":\"object\"}"
    };
}
pub(crate) use d_BlobManifest_d794e44a;

macro_rules! d_BlobRef_2e7d4163 {
    () => {
        "\"BlobRef\":{\"$ref\":\"#/$defs/DigestMultibase\",\"description\":\"The name of one blob: the digest of its BlobManifest, taken over the manifest's RFC 8785 (JCS) canonicalization. sha2-256 is RECOMMENDED and MUST be implemented. Content addressing over ciphertext, never plaintext, so a BlobRef says nothing about what the file contains, and two uploads of one file have different BlobRefs (a fresh `fileId` gives a different key, and so different ciphertext). Rooms cannot be correlated by the files they share. Compared as decoded multihash bytes, never as encoded strings. A BlobRef is defined over the manifest's JSON, as this schema states it and RFC 8785 canonicalizes it, never over any binding's generated type: two bindings that model the manifest as distinct types still compute the same BlobRef from the same JSON.\",\"title\":\"BlobRef\"}"
    };
}
