macro_rules! d_BreakGlass_23ea02f0 {
    () => {
        "\"BreakGlass\":{\"additionalProperties\":false,\"description\":\"How a self-granted right came to be, and whether another administrator has since ratified it. A record whose `breakGlass` has no `ratifiedBy` is **unratified**: it is live and published like any other right, it does not count toward the last-owner or last-admin invariants, and any community administrator or namespace admin of its namespace may revoke it. Ratification (git-ns/right/ratify) sets `ratifiedBy` and `ratifiedAt`; from then on the record is an ordinary grant, and `breakGlass` stays as its history. Never published to the Trust Registry.\",\"properties\":{\"by\":{\"$ref\":\"#/$defs/Did\",\"description\":\"Who broke the glass: always the record's `subject`, restated so the flag reads on its own.\"},\"effectiveAt\":{\"description\":\"When the right takes effect, where the community's policy imposed a delay. Absent: it took effect at `recordedAt`. Until this instant the record confers nothing and is not published, and any administrator who may revoke it may do so.\",\"format\":\"date-time\",\"type\":\"string\"},\"justification\":{\"description\":\"The actor's statement of why nobody else could grant this right. Shown to every community administrator, every namespace admin of the namespace and every owner of the resource; kept in the audit record; never published.\",\"maxLength\":2048,\"minLength\":1,\"pattern\":\"\\\\S\",\"type\":\"string\"},\"ratifiedAt\":{\"description\":\"When it was ratified. Present exactly when `ratifiedBy` is.\",\"format\":\"date-time\",\"type\":\"string\"},\"ratifiedBy\":{\"$ref\":\"#/$defs/Did\",\"description\":\"The administrator who ratified the record — never its subject. Absent while unratified.\"},\"recordedAt\":{\"description\":\"When the VTC recorded the break-glass.\",\"format\":\"date-time\",\"type\":\"string\"}},\"required\":[\"by\",\"recordedAt\",\"justification\"],\"title\":\"BreakGlass\",\"type\":\"object\"}"
    };
}
pub(crate) use d_BreakGlass_23ea02f0;

