macro_rules! d_FaceReach_a686487a {
    () => {
        "\"FaceReach\":{\"description\":\"Where a pool face may be worn. `anywhere` is the default and what an absent member means. `only` names the contexts it may be worn in, and a maintainer MUST refuse to wear it in any other (persona/binding/set `outsideReach`).\\n\\nA tagged object rather than a bare list of contexts, deliberately: an empty list has been read as both 'unrestricted' and 'nowhere' in this family's neighbours, and a shape where the two cannot be confused is worth more than one where they must be remembered. So `only` requires at least one context, and 'nowhere' is not a reach — it is a retired face.\\n\\nA context-local face has no reach: it lives in its context and is worn there by construction.\",\"oneOf\":[{\"additionalProperties\":false,\"properties\":{\"kind\":{\"const\":\"anywhere\"}},\"required\":[\"kind\"],\"type\":\"object\"},{\"additionalProperties\":false,\"properties\":{\"contextIds\":{\"items\":{\"minLength\":1,\"type\":\"string\"},\"maxItems\":256,\"minItems\":1,\"type\":\"array\",\"uniqueItems\":true},\"kind\":{\"const\":\"only\"}},\"required\":[\"kind\",\"contextIds\"],\"type\":\"object\"}],\"title\":\"FaceReach\"}"
    };
}
pub(crate) use d_FaceReach_a686487a;

macro_rules! d_FacetColour_d43978d8 {
    () => {
        "\"FacetColour\":{\"description\":\"**Superseded by `WorldColour`** — the same set, under the name the rest of the family now uses. Retained because `persona/facet/*` is retired in favour of `persona/world/*`, and a retired specification's schema is frozen, so the definition it references has to stay. New work references `WorldColour`. A colour **name**, resolved by each consumer against its own palette — never a hex value or any other literal. Two reasons, and both are about the consumer rather than the holder. A literal cannot be legible in a terminal, in a light theme and in a dark one at once, so a stored `#8B0000` is a colour that is wrong somewhere and the holder has no way to know where. And a consumer that reserves colours to mean something — an error, a warning, an irreversible act — must be able to keep a holder's decorative choice out of that channel; it cannot do that with an arbitrary value, and it can do it trivially with a closed set it maps itself. The eight members are chosen to be distinguishable from one another and deliberately carry no status connotation: none is named for success, warning or danger.\",\"enum\":[\"slate\",\"indigo\",\"teal\",\"moss\",\"sand\",\"clay\",\"rose\",\"plum\"],\"title\":\"FacetColour\",\"type\":\"string\"}"
    };
}
pub(crate) use d_FacetColour_d43978d8;

macro_rules! d_FileManifest_46391ddf {
    () => {
        "\"FileManifest\":{\"additionalProperties\":false,\"description\":\"Everything that describes a file. On an `attributed` or `private` room it is the `file` member of the sealed record body: sealed with the record, signed by the record's author, and never seen by the host. On an `open` room it is the `file` member of the record's `cleartext` (rooms/records/put/0.4), carrying its own `fileKey`, and the host reads it like the rest of the record. Defined here so that clients interoperate.\\n\\n**Byte encodings.** In every derivation below, `fileId` is its **32 decoded bytes**, never its base64url text; `roomId` is the **UTF-8 bytes** of the room identifier exactly as it appears on the wire; string constants are their ASCII bytes; `u8`, `u32be` and `u64be` are unsigned integers of that width, big-endian. Epochs are unsigned 64-bit on the wire. An implementation that holds epochs in a narrower type **MUST** refuse a value it cannot represent with `malformedRequest` (or, reading a manifest, refuse the file), and **MUST NOT** truncate it.\\n\\n**The file key.** `file_key = HKDF-SHA256(ikm = storage_key(epoch), salt = fileId, info = \\\"openvtc/room/file/v1\\\" || roomId || u64be(epoch))`, where `storage_key(epoch)` is the room's per-epoch storage key, the one records are sealed under. It is derived per file and never stored. It is bound to the room and the epoch, so a key released for one room cannot open a blob relocated from another, and releasing it exposes one file and nothing else.\\n\\n**The file key on an `open` room.** An open room has no group and so no storage key to derive from. There the uploader mints the file key itself — 32 bytes from a cryptographically secure random source, for this file only — and carries it in `fileKey`; a reader uses that key and derives nothing. Everything else below (padding, STREAM, the associated data, reading) is the same on every tier, with `epoch` the room's epoch when the file was written. `fileKey` **MUST** be present in an open room's manifest and **MUST** be absent from a sealed record body's, where the key is derived; a reader **MUST** refuse a file whose manifest breaks either rule. The key in the clear withholds nothing from the host or from anyone it serves the record to — the open tier withholds nothing from them — but it keeps the stored blob opaque to whoever holds only the storage, and keeps one blob format, and one reader, for every tier.\\n\\n**Padding.** With `padding: \\\"padme\\\"`, the plaintext of length `L = size` is extended with zero bytes to `padme(L)`: for `L < 2`, `padme(L) = L`; otherwise `E = floor(log2 L)`, `S = floor(log2 E) + 1`, `z = E − S`, `mask = 2^z − 1`, and `padme(L) = (L + mask) & ~mask`. The padded length is `padme(size)`; without padding it is `size`. Padding bytes **MUST** be zero.\\n\\n**The STREAM construction.** The padded plaintext is cut into `segmentSize`-byte segments, the last holding the remainder; an empty plaintext is one empty final segment. Segment `i` is sealed with ChaCha20-Poly1305 under `file_key`, with nonce `u32be(0) || u64be(i)` and associated data `\\\"openvtc/room/file/v1\\\" || roomId || fileId || u64be(epoch) || u64be(i) || u8(final)`, where `final` is 1 on the last segment and 0 on every other. A host that truncates, reorders or splices ciphertext produces an authentication failure, never a shorter or rearranged file. The nonces are counters, so a `file_key` MUST NOT seal two different files; a fresh random `fileId` is what guarantees it. Each sealed segment is one transfer chunk of the blob (BlobManifest), so `segmentSize + 16` is the blob's `chunks.chunkSize`, and an empty file is one 16-byte chunk.\\n\\n**Reading.** A reader opens the record, derives or obtains the file key, and **MUST**, before trusting a byte:\\n- check that the blob's `chunks.chunkSize` equals `segmentSize + 16` and that `chunks.chunkCount` equals `max(1, ceil(paddedLength / segmentSize))`, and refuse the file otherwise;\\n- decrypt every segment in order, refusing the file on any authentication failure or on a final flag anywhere but the last segment;\\n- check that the decrypted length equals the padded length, that every padding byte is zero, and, after removing the padding, that the plaintext matches `digest`.\\n\\nA reader **MUST** refuse a file that fails any check, and **MUST NOT** present it with a warning instead. A reader that streams **MUST NOT** treat the plaintext as received — save it under its final name, render it, or hand it to another component — until the digest has verified; it writes to a temporary destination and discards that destination on a mismatch.\\n\\n**An image's size and preview.** `width`, `height` and `preview` are OPTIONAL and advisory: they let a reader lay out an image, and show something, before it fetches and decrypts the blob. A reader that fetches the file checks them against the bytes — the decoded image's dimensions, and that the file is an image at all — and on a mismatch uses the bytes and discards them; it MUST NOT treat any of them as evidence about the file. On `attributed` and `private` rooms they are inside the sealed, signed body like the rest of the manifest, so the host learns nothing from them; on an `open` room they are in the clear, as everything there is, and a writer carries them only with `rooms/records/put/0.5` or later. A writer uses them only once the room's profile lists them in `recordMembers` (`RoomProfile`), as with the other members a reader that predates them refuses.\",\"properties\":{\"blobRef\":{\"$ref\":\"#/$defs/BlobRef\"},\"digest\":{\"$ref\":\"#/$defs/DigestMultibase\",\"description\":\"Digest of the plaintext bytes. On `attributed` and `private` rooms it is signed, with the rest of the record body, by the record's author, so a reader that verifies it knows which member put exactly these bytes there. On an `open` room it is the writer's claim as the host stores it, like the rest of the record.\"},\"epoch\":{\"description\":\"The epoch whose storage key the file key derives from. Usually the record's own epoch; a record rewritten under a later epoch that keeps the same blob keeps the file's original epoch here. Unsigned 64-bit; see Byte encodings.\",\"minimum\":1,\"type\":\"integer\"},\"fileId\":{\"description\":\"32 random bytes, base64url without padding, minted by the uploader for this file and never reused. The salt of the file key.\",\"pattern\":\"^[A-Za-z0-9_-]{43}$\",\"type\":\"string\"},\"fileKey\":{\"description\":\"The file key itself, 32 bytes base64url without padding: present on an `open` room only, where there is no storage key to derive it from. Minted by the uploader from a cryptographically secure random source for this one file and never reused. MUST be absent on `attributed` and `private` rooms, where the key is derived and never stored.\",\"pattern\":\"^[A-Za-z0-9_-]{43}$\",\"type\":\"string\"},\"height\":{\"description\":\"The image's height in pixels, as the uploader read it. Advisory. A writer sets `width` and `height` together or neither; a reader ignores one without the other. A reader checks it against the decoded image.\",\"maximum\":1048576,\"minimum\":1,\"type\":\"integer\"},\"mediaType\":{\"description\":\"IANA media type, without parameters. Advisory: a reader decides how to render from the bytes and its own policy, never from this alone.\",\"maxLength\":255,\"pattern\":\"^[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]*/[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]*$\",\"type\":\"string\"},\"name\":{\"description\":\"The file's name as the uploader gave it. Sealed on `attributed` and `private` rooms, where the host never sees it; in the clear on `open` ones. Readers MUST treat it as untrusted text: strip path separators before using it as a local file name, and never interpret it as markup.\",\"maxLength\":255,\"minLength\":1,\"type\":\"string\"},\"padding\":{\"description\":\"Whether the plaintext was padded before sealing, so that ciphertext sizes do not fingerprint known documents. `padme`: zero bytes appended to reach `padme(size)`, the formula above. Absent means `none`. The padding is inside the final segments, and a reader checks it is zero and removes it by truncating to `size`.\",\"enum\":[\"none\",\"padme\"],\"type\":\"string\"},\"preview\":{\"additionalProperties\":false,\"description\":\"A small image standing in for the file until it is fetched: at most 8192 bytes before encoding, enough for a blurred thumbnail and small enough not to swell the record every listing reader opens. A reader renders it only as a raster image it decodes itself — never as SVG or any other type that can carry active content, never as a link, never fetching anything — and replaces it with the file once fetched. It is the uploader's rendering of the file, not a digest of it: a reader MUST NOT present it as the file's contents.\",\"properties\":{\"data\":{\"description\":\"The preview's bytes, base64url without padding: at most 8192 bytes decoded.\",\"maxLength\":10923,\"minLength\":1,\"pattern\":\"^[A-Za-z0-9_-]+$\",\"type\":\"string\"},\"mediaType\":{\"description\":\"The preview's own media type. Raster types only.\",\"enum\":[\"image/jpeg\",\"image/png\",\"image/webp\"],\"type\":\"string\"}},\"required\":[\"mediaType\",\"data\"],\"type\":\"object\"},\"segmentSize\":{\"description\":\"Plaintext bytes per STREAM segment: the transfer chunk size less the 16-byte tag, so that one sealed segment is one chunk.\",\"maximum\":262128,\"minimum\":16368,\"type\":\"integer\"},\"size\":{\"description\":\"Plaintext bytes, before padding. The decrypted length is `padme(size)` with `padme` padding and `size` without.\",\"minimum\":0,\"type\":\"integer\"},\"width\":{\"description\":\"The image's width in pixels, as the uploader read it. Advisory. A writer sets `width` and `height` together or neither; a reader ignores one without the other. A reader checks it against the decoded image.\",\"maximum\":1048576,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"fileId\",\"name\",\"size\",\"digest\",\"epoch\",\"segmentSize\",\"blobRef\"],\"title\":\"FileManifest\",\"type\":\"object\"}"
    };
}
pub(crate) use d_FileManifest_46391ddf;

macro_rules! d_Floor_12ea9f0c {
    () => {
        "\"Floor\":{\"additionalProperties\":false,\"properties\":{\"allowAal1IfNonEscalating\":{\"description\":\"Carve-out for non-escalating self-service operations (notably acl/swap-key key-rotation and method-enrolment). When `true` and the maintainer verifies the request does not escalate (its resulting AclEntry's role and scopes are a subset of the caller's existing entry, and the caller acts on its own entry), the operation is admitted at AAL1 even though `mode` requires AAL2 — so a holder with no authenticator yet can still bootstrap/rotate. Omitted is equivalent to `false` (the correct default for escalating operations such as acl/grant, change-role, revoke, context/delete, key/revoke): a caller lacking a usable step-up method is denied (fail-closed) rather than silently downgraded to AAL1.\",\"type\":\"boolean\"},\"mode\":{\"description\":\"Minimum mode required to perform the operation. `none` = AAL1 permitted (no step-up). `self` = the caller must elevate its own session (AAL2 via its own authenticator). `delegated` = a separate approver named on the caller's AclEntry (`stepUp.approver`) MUST ratify (AAL2 via auth/step-up/approve-request). `delegated-any` = any VID satisfying the maintainer's approver criterion MAY ratify. Strictness order for floor/override resolution: none < self < delegated-any < delegated.\",\"enum\":[\"none\",\"self\",\"delegated\",\"delegated-any\"],\"type\":\"string\"},\"operation\":{\"description\":\"The operation-class this floor governs: a Trust Task type URI or slug (e.g. `acl/grant`, `acl/swap-key`, `context/delete`, `key/revoke`, `vault/release`), or `*` for the catch-all default applied when no more-specific floor matches.\",\"type\":\"string\"}},\"required\":[\"operation\",\"mode\"],\"title\":\"StepUpFloor\",\"type\":\"object\"}"
    };
}
pub(crate) use d_Floor_12ea9f0c;

