macro_rules! d_ForgeEvent_cb8c689f {
    () => {
        "\"ForgeEvent\":{\"description\":\"One forge-neutral event, discriminated by `type`. The specification's event table says what each type means and what the VTC does with it.\",\"oneOf\":[{\"additionalProperties\":false,\"properties\":{\"forgeId\":{\"$ref\":\"#/$defs/ForgeId\"},\"from\":{\"$ref\":\"#/$defs/RepoResource\"},\"to\":{\"$ref\":\"#/$defs/RepoResource\"},\"type\":{\"const\":\"repoRenamed\"}},\"required\":[\"type\",\"forgeId\",\"from\",\"to\"],\"title\":\"RepoRenamed\",\"type\":\"object\"},{\"additionalProperties\":false,\"properties\":{\"forgeId\":{\"$ref\":\"#/$defs/ForgeId\"},\"from\":{\"$ref\":\"#/$defs/RepoResource\"},\"to\":{\"$ref\":\"#/$defs/RepoResource\"},\"type\":{\"const\":\"repoTransferred\"}},\"required\":[\"type\",\"forgeId\",\"from\",\"to\"],\"title\":\"RepoTransferred\",\"type\":\"object\"},{\"additionalProperties\":false,\"properties\":{\"forgeId\":{\"$ref\":\"#/$defs/ForgeId\"},\"resource\":{\"$ref\":\"#/$defs/RepoResource\"},\"type\":{\"const\":\"repoCreatedUnmanaged\"}},\"required\":[\"type\",\"forgeId\",\"resource\"],\"title\":\"RepoCreatedUnmanaged\",\"type\":\"object\"},{\"additionalProperties\":false,\"properties\":{\"forgeId\":{\"$ref\":\"#/$defs/ForgeId\"},\"resource\":{\"$ref\":\"#/$defs/RepoResource\"},\"type\":{\"const\":\"repoDeleted\"}},\"required\":[\"type\",\"forgeId\",\"resource\"],\"title\":\"RepoDeleted\",\"type\":\"object\"},{\"additionalProperties\":false,\"properties\":{\"account\":{\"$ref\":\"#/$defs/ForgeAccount\"},\"forgeId\":{\"$ref\":\"#/$defs/ForgeId\"},\"resource\":{\"$ref\":\"#/$defs/RepoResource\"},\"role\":{\"$ref\":\"#/$defs/ForgeRole\",\"description\":\"The role the account now holds. Absent: the account holds no role now.\"},\"type\":{\"const\":\"roleChanged\"}},\"required\":[\"type\",\"forgeId\",\"resource\",\"account\"],\"title\":\"RoleChanged\",\"type\":\"object\"},{\"additionalProperties\":false,\"properties\":{\"forgeId\":{\"$ref\":\"#/$defs/ForgeId\"},\"requiredCheck\":{\"description\":\"Whether the forge still refuses merges without a passing verify-trust check, with no bypass.\",\"type\":\"boolean\"},\"resource\":{\"$ref\":\"#/$defs/RepoResource\"},\"type\":{\"const\":\"protectionChanged\"}},\"required\":[\"type\",\"forgeId\",\"resource\",\"requiredCheck\"],\"title\":\"ProtectionChanged\",\"type\":\"object\"},{\"additionalProperties\":false,\"properties\":{\"type\":{\"const\":\"installationRemoved\"}},\"required\":[\"type\"],\"title\":\"InstallationRemoved\",\"type\":\"object\"},{\"additionalProperties\":false,\"properties\":{\"account\":{\"$ref\":\"#/$defs/ForgeAccount\"},\"jobId\":{\"$ref\":\"#/$defs/JobId\",\"description\":\"The beginAccountLink job.\"},\"type\":{\"const\":\"accountLinked\"}},\"required\":[\"type\",\"jobId\",\"account\"],\"title\":\"AccountLinked\",\"type\":\"object\"},{\"additionalProperties\":false,\"properties\":{\"jobId\":{\"$ref\":\"#/$defs/JobId\",\"description\":\"The beginBind job.\"},\"kind\":{\"enum\":[\"organization\",\"user\"],\"type\":\"string\"},\"ownerId\":{\"$ref\":\"#/$defs/ForgeId\",\"description\":\"The forge's id for the owner, which survives renames.\"},\"type\":{\"const\":\"bindCompleted\"}},\"required\":[\"type\",\"jobId\",\"ownerId\",\"kind\"],\"title\":\"BindCompleted\",\"type\":\"object\"},{\"additionalProperties\":false,\"properties\":{\"ladder\":{\"description\":\"The levels the forge offers as a direct role on a repository in the namespace, lowest first, without `none` (which every forge has). Every role in `roleMap` and in each `repos[].roleMap` is `none` or one of these.\",\"items\":{\"$ref\":\"#/$defs/MappedRole\"},\"maxItems\":5,\"minItems\":1,\"type\":\"array\",\"uniqueItems\":true},\"repos\":{\"description\":\"Repositories whose own map differs from `roleMap`, each at most once. Absent or empty: every repository uses `roleMap`.\",\"items\":{\"additionalProperties\":false,\"properties\":{\"resource\":{\"$ref\":\"#/$defs/RepoResource\"},\"roleMap\":{\"$ref\":\"#/$defs/RoleMap\"}},\"required\":[\"resource\",\"roleMap\"],\"type\":\"object\"},\"maxItems\":1000,\"type\":\"array\"},\"roleMap\":{\"$ref\":\"#/$defs/RoleMap\"},\"stale\":{\"description\":\"Repositories whose forge roles the bridge last projected under a different map from the one it now applies to them. Absent or empty: none.\",\"items\":{\"$ref\":\"#/$defs/RepoResource\"},\"maxItems\":10000,\"type\":\"array\",\"uniqueItems\":true},\"type\":{\"const\":\"roleMapReported\"}},\"required\":[\"type\",\"roleMap\",\"ladder\"],\"title\":\"RoleMapReported\",\"type\":\"object\"},{\"additionalProperties\":false,\"properties\":{\"action\":{\"description\":\"`opened` — the pull request was just opened. `reopened` — a closed, unmerged pull request was reopened.\",\"enum\":[\"opened\",\"reopened\"],\"title\":\"PullRequestAction\",\"type\":\"string\"},\"actor\":{\"$ref\":\"#/$defs/ForgeAccount\",\"description\":\"The account that performed this action: the author for `opened`, whoever reopened the pull request for `reopened`.\"},\"author\":{\"$ref\":\"#/$defs/ForgeAccount\",\"description\":\"The account that opened the pull request.\"},\"draft\":{\"description\":\"Whether the pull request is a draft. Absent: the bridge does not know, or the forge has no drafts.\",\"type\":\"boolean\"},\"forgeId\":{\"$ref\":\"#/$defs/ForgeId\",\"description\":\"The forge's id for the repository the pull request targets.\"},\"fromFork\":{\"description\":\"Whether the pull request's head branch lives in another repository (a fork). Absent: the bridge does not know.\",\"type\":\"boolean\"},\"number\":{\"description\":\"The pull request's number in `resource`.\",\"minimum\":1,\"type\":\"integer\"},\"resource\":{\"$ref\":\"#/$defs/RepoResource\",\"description\":\"The repository the pull request targets (its base repository).\"},\"type\":{\"const\":\"pullRequestOpened\"}},\"required\":[\"type\",\"forgeId\",\"resource\",\"number\",\"action\",\"author\",\"actor\"],\"title\":\"PullRequestOpened\",\"type\":\"object\"}],\"title\":\"ForgeEvent\",\"type\":\"object\"}"
    };
}
