macro_rules! d_GrantState_78dbcd95 {
    () => {
        "\"GrantState\":{\"description\":\"A stored grant's state. `active`: valid; the member is attached whenever the principal is connected. `suspended`: the member DID proved control with a key that signed none of its active grants (the unknown-key rule); terminal — the grant cannot be resumed and must be recreated by a fresh member signature. `staleKey`: the key that signed the grant is no longer in the member DID's current authentication relationship; terminal — it does not become active again if the key reappears. `expired`: an active grant past its effective expiry; computed when read, never stored. `epochRevoked`: the member DID advanced its epoch with messaging/mux/revoke-all. A grant revoked with messaging/mux/revoke has no state: it is deleted. A dead grant (every state but `active`) stays listable for the mediator's retention window after its effective expiry, then is pruned.\",\"enum\":[\"active\",\"suspended\",\"staleKey\",\"expired\",\"epochRevoked\"],\"title\":\"GrantState\",\"type\":\"string\"}"
    };
}
