macro_rules! d_GrantStatement_6d9867d5 {
    () => {
        "\"GrantStatement\":{\"additionalProperties\":false,\"description\":\"A member DID's standing statement that the named principal may carry its traffic at this mediator, on any connection, until `exp`, within `scope`, under the member's current `epoch`. Signed by the member with an embedded Data Integrity proof whose purpose is `authentication`, and stored verbatim by the mediator as the only evidence of the delegation.\",\"properties\":{\"audience\":{\"$ref\":\"#/$defs/MuxDid\",\"description\":\"The mediator's DID. A statement names exactly one mediator and is refused by every other.\"},\"epoch\":{\"description\":\"The member DID's current epoch at the mediator. Only messaging/mux/revoke-all advances it.\",\"minimum\":0,\"type\":\"integer\"},\"exp\":{\"description\":\"JWT NumericDate (RFC 7519 §2): when the statement stops being accepted. REQUIRED; MUST be after `iat` and in the future.\",\"minimum\":0,\"type\":\"integer\"},\"grantId\":{\"$ref\":\"#/$defs/GrantId\"},\"iat\":{\"description\":\"JWT NumericDate (RFC 7519 §2), whole seconds since 1970-01-01T00:00:00Z UTC: when the statement was signed. MUST NOT be more than 60 seconds in the mediator's future.\",\"minimum\":0,\"type\":\"integer\"},\"issuer\":{\"$ref\":\"#/$defs/MuxDid\",\"description\":\"The member DID: the signer, and the DID the statement concerns.\"},\"principal\":{\"$ref\":\"#/$defs/MuxDid\",\"description\":\"The principal DID that may carry the member's traffic. MUST differ from `issuer`.\"},\"proof\":{\"$ref\":\"#/$defs/MuxDataIntegrityProof\"},\"scope\":{\"$ref\":\"#/$defs/StatementScope\"},\"type\":{\"const\":\"muxGrant\",\"description\":\"Always `muxGrant`; names the statement kind, so a statement of one kind is never accepted as another.\",\"type\":\"string\"}},\"required\":[\"type\",\"issuer\",\"audience\",\"grantId\",\"principal\",\"scope\",\"epoch\",\"iat\",\"exp\",\"proof\"],\"title\":\"GrantStatement\",\"type\":\"object\"}"
    };
}
