macro_rules! d_KeyOrigin_8e7dc5f0 {
    () => {
        "\"KeyOrigin\":{\"default\":\"derived\",\"description\":\"Where the private key came from. `derived` means the maintainer generated it from a seed it holds and can reproduce it from `derivationPath`; `imported` means it arrived from outside and exists only as stored material; `internal` means the maintainer generated it from a CSPRNG and it is reproducible from nothing at all. The distinction is operationally load-bearing: a `derived` key survives a seed restore, an `imported` one is lost unless it was backed up separately, and an `internal` one cannot be recovered by any means once the maintainer's storage is gone. This member is also the only way a consumer can confirm that a `keys/create` request for an `internal` key was honoured rather than silently downgraded to a derived one — see that specification's `internal` member.\",\"enum\":[\"derived\",\"imported\",\"internal\"],\"title\":\"KeyOrigin\",\"type\":\"string\"}"
    };
}
pub(crate) use d_KeyOrigin_8e7dc5f0;

macro_rules! d_KeyRecord_a42d2826 {
    () => {
        "\"KeyRecord\":{\"additionalProperties\":false,\"properties\":{\"contextId\":{\"description\":\"Scope the key belongs to. **Absence is not 'every scope'** — a key with no context is reachable only by a caller with unrestricted authority over the maintainer, which is the more restrictive reading, and a consumer that treats absence as a wildcard inverts the guarantee.\",\"type\":\"string\"},\"createdAt\":{\"description\":\"RFC 3339 timestamp at which the key was created or imported.\",\"format\":\"date-time\",\"type\":\"string\"},\"derivationPath\":{\"description\":\"Hierarchical-deterministic path the key was derived at, when `origin` is `derived`. Absent for imported keys, which have no path.\",\"type\":\"string\"},\"exportable\":{\"$comment\":\"No JSON Schema `default` is declared here on purpose. A declared default is materialised by the generated bindings — the field becomes non-optional with a serde default — so an absent member reappears as an explicit `true` on re-serialisation, which breaks round-trip idempotence for every record written before this member existed. The permissive reading is stated in prose above, where a binding cannot act on it.\",\"description\":\"Whether the private half may be released to a caller. `false` means the custodian refuses every export of this key and can only be asked to *use* it — signing, key agreement — so the material never leaves. **Absence means the key may be exported.** That is the permissive reading, and it is deliberate: it is what every record written before this member existed already meant, so a custodian adding the member cannot silently retract access to keys its callers already hold. A consumer MUST NOT infer the converse — absence is not a statement that export was considered and allowed. Marking a key non-exportable does not make it unrecoverable: a custodian's own whole-store backup is a different mechanism from an export to a caller, and this member does not speak to it.\",\"type\":\"boolean\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"keyId\":{\"description\":\"Maintainer-scoped identifier for the key. Stable for the key's lifetime except through an explicit `keys/rename`.\",\"minLength\":1,\"type\":\"string\"},\"keyType\":{\"$ref\":\"#/$defs/KeyType\"},\"label\":{\"description\":\"Optional human-readable label. Operator-facing only; carries no authorization meaning.\",\"maxLength\":256,\"type\":\"string\"},\"origin\":{\"$ref\":\"#/$defs/KeyOrigin\"},\"publicKey\":{\"description\":\"The public half, multibase-encoded. The private half is never carried by any keys/* response.\",\"minLength\":1,\"type\":\"string\"},\"seedId\":{\"description\":\"Identifier of the seed the key was derived from, when the maintainer holds more than one. Absent for imported keys.\",\"minimum\":0,\"type\":\"integer\"},\"status\":{\"$ref\":\"#/$defs/KeyStatus\"},\"updatedAt\":{\"description\":\"RFC 3339 timestamp of the last change to the record (rename, revocation).\",\"format\":\"date-time\",\"type\":\"string\"}},\"required\":[\"keyId\",\"keyType\",\"status\",\"publicKey\",\"createdAt\"],\"title\":\"KeyRecord\",\"type\":\"object\"}"
    };
}
pub(crate) use d_KeyRecord_a42d2826;

