        "\"PolicyModule\":{\"additionalProperties\":false,\"properties\":{\"appliesTo\":{\"description\":\"List of trust contexts this policy applies to. Empty array = applies to all contexts (the default policy).\",\"items\":{\"type\":\"string\"},\"type\":\"array\",\"uniqueItems\":true},\"createdAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"description\":{\"maxLength\":1024,\"type\":\"string\"},\"enabled\":{\"default\":true,\"type\":\"boolean\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"id\":{\"minLength\":1,\"type\":\"string\"},\"module\":{\"description\":\"Rego source code. The maintainer's evaluator entry point is the package's `decision` rule, returning a PolicyDecision.\",\"minLength\":1,\"type\":\"string\"},\"name\":{\"description\":\"Human-readable name (e.g. \\\"default vault policy\\\", \\\"bank-site step-up\\\").\",\"maxLength\":128,\"minLength\":1,\"type\":\"string\"},\"priority\":{\"description\":\"When multiple policies match a request, evaluation order is by priority descending. The first to return a non-`null` decision wins.\",\"maximum\":1000,\"minimum\":0,\"type\":\"integer\"},\"updatedAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"version\":{\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"id\",\"name\",\"module\",\"version\",\"createdAt\",\"updatedAt\"],\"title\":\"PolicyModule\",\"type\":\"object\"}"
