macro_rules! d_PresignBatch_a94de677 {
    () => {
        "\"PresignBatch\":{\"additionalProperties\":false,\"description\":\"`s3-static-presign` only: up to 128 operations on **one** object, `prefix` + `objectKey`, and at most one multipart upload of it. Each operation becomes one presigned request, sealed together. Consistency rules JSON Schema cannot state, which the custodian enforces: `uploadId` is present exactly when an operation needs it (`upload-part`, `list-parts`, `complete-multipart`, `abort-multipart`) and absent when the batch holds `create-multipart`; no two operations are identical; no two `upload-part` operations name the same `partNumber`.\",\"properties\":{\"objectKey\":{\"description\":\"The object's name within `prefix`. Every request in the batch names `prefix` + `objectKey` and no other object.\",\"maxLength\":1024,\"minLength\":1,\"pattern\":\"^[A-Za-z0-9._-]+$\",\"type\":\"string\"},\"prefix\":{\"$ref\":\"#/$defs/ProviderObjectPrefix\"},\"requests\":{\"items\":{\"$ref\":\"#/$defs/PresignRequest\"},\"maxItems\":128,\"minItems\":1,\"type\":\"array\"},\"uploadId\":{\"description\":\"The multipart upload the batch's multipart operations act on, as storage returned it from CreateMultipartUpload. Signed into each such request's query, percent-encoded by the SigV4 encoder, never interpolated.\",\"maxLength\":1024,\"minLength\":1,\"pattern\":\"^[A-Za-z0-9._~+/=-]+$\",\"type\":\"string\"}},\"required\":[\"prefix\",\"objectKey\",\"requests\"],\"title\":\"PresignBatch\",\"type\":\"object\"}"
    };
}
pub(crate) use d_PresignBatch_a94de677;

macro_rules! d_PresignBatch_c1c6bc40 {
    () => {
        "\"PresignBatch\":{\"additionalProperties\":false,\"description\":\"`s3-static-presign` only: up to 64 operations on **one** object, `prefix` + `objectKey`, and at most one multipart upload of it. Each operation becomes one presigned request, sealed together. Consistency rules JSON Schema cannot state, which the custodian enforces: `uploadId` is present exactly when an operation needs it (`upload-part`, `list-parts`, `complete-multipart`, `abort-multipart`) and absent when the batch holds `create-multipart`; no two operations are identical; no two `upload-part` operations name the same `partNumber`.\",\"properties\":{\"objectKey\":{\"description\":\"The object's name within `prefix`. Every request in the batch names `prefix` + `objectKey` and no other object.\",\"maxLength\":1024,\"minLength\":1,\"pattern\":\"^[A-Za-z0-9._-]+$\",\"type\":\"string\"},\"prefix\":{\"$ref\":\"#/$defs/ProviderObjectPrefix\"},\"requests\":{\"description\":\"At most 64. Each presigned request is bearer authority until it expires, so a batch holds what a consumer can use within its lifetime; a larger upload asks again, or writes larger parts. A batch whose sealed answer would exceed `sealedCredential`'s bound is refused with `responseTooLarge`, whatever its count.\",\"items\":{\"$ref\":\"#/$defs/PresignRequest\"},\"maxItems\":64,\"minItems\":1,\"type\":\"array\"},\"uploadId\":{\"description\":\"The multipart upload the batch's multipart operations act on, as storage returned it from CreateMultipartUpload. Signed into each such request's query, percent-encoded by the SigV4 encoder, never interpolated.\",\"maxLength\":1024,\"minLength\":1,\"pattern\":\"^[A-Za-z0-9._~+/=-]+$\",\"type\":\"string\"}},\"required\":[\"prefix\",\"objectKey\",\"requests\"],\"title\":\"PresignBatch\",\"type\":\"object\"}"
    };
}
pub(crate) use d_PresignBatch_c1c6bc40;

macro_rules! d_PresignRequest_80ca5b92 {
    () => {
        "\"PresignRequest\":{\"description\":\"One operation to presign, discriminated by `operation`. The ceiling action each needs is in `PresignOperation`.\",\"oneOf\":[{\"additionalProperties\":false,\"description\":\"PutObject of the whole object, bound to its exact length and SHA-256.\",\"properties\":{\"checksumSha256\":{\"$ref\":\"#/$defs/ChecksumSha256\"},\"contentLength\":{\"description\":\"The object's exact length in bytes, signed into the request as `Content-Length`. At most 5 GiB, S3's single-request ceiling.\",\"maximum\":5368709120,\"minimum\":0,\"type\":\"integer\"},\"operation\":{\"const\":\"put\",\"type\":\"string\"}},\"required\":[\"operation\",\"contentLength\",\"checksumSha256\"],\"title\":\"PresignPut\",\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"GetObject.\",\"properties\":{\"operation\":{\"const\":\"get\",\"type\":\"string\"}},\"required\":[\"operation\"],\"title\":\"PresignGet\",\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"HeadObject, with `x-amz-checksum-mode: ENABLED` signed so storage reports the object's checksum.\",\"properties\":{\"operation\":{\"const\":\"head\",\"type\":\"string\"}},\"required\":[\"operation\"],\"title\":\"PresignHead\",\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"DeleteObject.\",\"properties\":{\"operation\":{\"const\":\"delete\",\"type\":\"string\"}},\"required\":[\"operation\"],\"title\":\"PresignDelete\",\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"CreateMultipartUpload, with `x-amz-checksum-algorithm: SHA256` signed so every part of the upload must carry a SHA-256 checksum.\",\"properties\":{\"operation\":{\"const\":\"create-multipart\",\"type\":\"string\"}},\"required\":[\"operation\"],\"title\":\"PresignCreateMultipart\",\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"UploadPart of one part of `uploadId`, bound to its number, its exact length and its SHA-256.\",\"properties\":{\"checksumSha256\":{\"$ref\":\"#/$defs/ChecksumSha256\"},\"contentLength\":{\"description\":\"The part's exact length in bytes, signed into the request as `Content-Length`. At most 5 GiB, S3's part ceiling.\",\"maximum\":5368709120,\"minimum\":1,\"type\":\"integer\"},\"operation\":{\"const\":\"upload-part\",\"type\":\"string\"},\"partNumber\":{\"maximum\":10000,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"operation\",\"partNumber\",\"contentLength\",\"checksumSha256\"],\"title\":\"PresignUploadPart\",\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"ListParts of `uploadId`: each part's number, length, ETag and checksum, up to 1000 per page.\",\"properties\":{\"operation\":{\"const\":\"list-parts\",\"type\":\"string\"},\"partNumberMarker\":{\"description\":\"List parts after this number. Absent, from the first.\",\"maximum\":10000,\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"operation\"],\"title\":\"PresignListParts\",\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"CompleteMultipartUpload of `uploadId`, bound to the assembled object's exact length.\",\"properties\":{\"contentLength\":{\"description\":\"The assembled object's exact length in bytes, signed into the request as `x-amz-mp-object-size`, so storage refuses a completion that would assemble any other size. At most 5 TiB, S3's object ceiling.\",\"maximum\":5497558138880,\"minimum\":0,\"type\":\"integer\"},\"operation\":{\"const\":\"complete-multipart\",\"type\":\"string\"}},\"required\":[\"operation\",\"contentLength\"],\"title\":\"PresignCompleteMultipart\",\"type\":\"object\"},{\"additionalProperties\":false,\"description\":\"AbortMultipartUpload of `uploadId`.\",\"properties\":{\"operation\":{\"const\":\"abort-multipart\",\"type\":\"string\"}},\"required\":[\"operation\"],\"title\":\"PresignAbortMultipart\",\"type\":\"object\"}],\"title\":\"PresignRequest\"}"
    };
}
pub(crate) use d_PresignRequest_80ca5b92;

macro_rules! d_ProfileEntry_3cd981fe {
    () => {
        "\"ProfileEntry\":{\"description\":\"One line of a profile, in exactly one of four forms. Together they are the whole of a profile's flexibility, and each exists for a case the others handle badly.\\n\\n`{ref}` — use the pool attribute, live. Editing the pool updates every profile that references it, which is the point.\\n\\n`{ref, pinVersion}` — use the value as it was at that version. For a profile that must keep presenting the value a counterparty already verified.\\n\\n`{ref, override}` — the same fact, a different value here. (\\\"In the gaming profile my display name is different.\\\")\\n\\n`{inline}` — a value that never enters the pool, and so never leaks into another profile.\\n\\nOmission is exclusion; there is no removal marker.\\n\\nAny form MAY carry a `slot` naming the role the entry plays in the profile — see `Slot`. A maintainer MUST refuse a profile in which two entries carry the same slot: a slot exists to answer one question with one entry.\",\"oneOf\":[{\"additionalProperties\":false,\"properties\":{\"ref\":{\"$ref\":\"#/$defs/Ulid\"},\"slot\":{\"$ref\":\"#/$defs/Slot\"}},\"required\":[\"ref\"]},{\"additionalProperties\":false,\"properties\":{\"pinVersion\":{\"$ref\":\"#/$defs/Version\"},\"ref\":{\"$ref\":\"#/$defs/Ulid\"},\"slot\":{\"$ref\":\"#/$defs/Slot\"}},\"required\":[\"ref\",\"pinVersion\"]},{\"additionalProperties\":false,\"properties\":{\"override\":{\"additionalProperties\":false,\"description\":\"Replaces the pool attribute's value for this profile only. `type`, `valueType` and `provenance` are inherited from the referenced attribute and MUST NOT be overridden — an override that changed provenance would let a self-asserted value present as attested.\",\"properties\":{\"label\":{\"maxLength\":128,\"type\":\"string\"},\"value\":{}},\"required\":[\"value\"],\"type\":\"object\"},\"ref\":{\"$ref\":\"#/$defs/Ulid\"},\"slot\":{\"$ref\":\"#/$defs/Slot\"}},\"required\":[\"ref\",\"override\"]},{\"additionalProperties\":false,\"properties\":{\"inline\":{\"additionalProperties\":false,\"properties\":{\"label\":{\"maxLength\":128,\"type\":\"string\"},\"provenance\":{\"$ref\":\"#/$defs/Provenance\"},\"type\":{\"$ref\":\"#/$defs/ClaimType\"},\"value\":{},\"valueType\":{\"$ref\":\"#/$defs/ValueType\"}},\"required\":[\"type\",\"valueType\",\"value\",\"provenance\"],\"type\":\"object\"},\"slot\":{\"$ref\":\"#/$defs/Slot\"}},\"required\":[\"inline\"]}],\"title\":\"ProfileEntry\",\"type\":\"object\"}"
    };
}
pub(crate) use d_ProfileEntry_3cd981fe;

macro_rules! d_Profile_a5c52015 {
    () => {
        "\"Profile\":{\"additionalProperties\":false,\"description\":\"A named projection over the pool. Agent-scoped, like the pool it draws from. `entries` is ordered and the order is display order.\",\"properties\":{\"createdAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"credentialRefs\":{\"description\":\"Vault identifiers of credentials associated with this profile as INVENTORY, distinct from the evidence relationship a `credentialBacked` attribute expresses. The two answer different questions — what can this persona prove, versus what backs this specific claim — and a consumer MUST NOT read one as the other.\",\"items\":{\"minLength\":1,\"type\":\"string\"},\"maxItems\":256,\"type\":\"array\"},\"entries\":{\"items\":{\"$ref\":\"#/$defs/ProfileEntry\"},\"maxItems\":256,\"type\":\"array\"},\"name\":{\"description\":\"The holder's name for this profile — \\\"Work\\\", \\\"Gaming\\\". Not disclosed.\",\"maxLength\":128,\"minLength\":1,\"type\":\"string\"},\"profileId\":{\"$ref\":\"#/$defs/Ulid\"},\"reach\":{\"$ref\":\"#/$defs/FaceReach\"},\"retiredAt\":{\"description\":\"When the face was retired. Present exactly when `status` is `retired`.\",\"format\":\"date-time\",\"type\":\"string\"},\"status\":{\"default\":\"active\",\"description\":\"`retired`: the face is worn nowhere, is left out of pickers and default listings, and cannot be worn until reinstated (persona/profile/retire, persona/profile/reinstate). Its disclosure history and every value it carries are kept — retiring is 'stop being this', not 'forget this'. Absent reads as `active`.\",\"enum\":[\"active\",\"retired\"],\"type\":\"string\"},\"updatedAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"version\":{\"$ref\":\"#/$defs/Version\"}},\"required\":[\"profileId\",\"name\",\"entries\",\"version\",\"updatedAt\"],\"title\":\"Profile\",\"type\":\"object\"}"
    };
}
pub(crate) use d_Profile_a5c52015;

macro_rules! d_ProofRung_2b660c93 {
    () => {
        "\"ProofRung\":{\"description\":\"How strongly a credential-backed claim is hidden when presented, ordered most private first. `predicate` proves a statement over a claim without disclosing the claim. `derived` discloses exactly the claims needed via an unlinkable derived proof, so two presentations cannot be joined. `selectiveDisclosure` discloses exactly the claims needed but carries the issuer's signature unchanged, so two presentations ARE linkable. `whole` discloses the entire credential.\\n\\nThe distinction between the first two and the last two is of kind, not degree: only `predicate` and `derived` avoid handing two verifiers a join key. A maintainer MUST default to the highest rung the credential's format supports, and MUST NOT silently fall to a lower one — a request that cannot be satisfied at the rung a producer asked for is refused, because a silent privacy downgrade discloses material the holder believed was hidden.\",\"enum\":[\"predicate\",\"derived\",\"selectiveDisclosure\",\"whole\"],\"title\":\"ProofRung\",\"type\":\"string\"}"
    };
}
pub(crate) use d_ProofRung_2b660c93;

macro_rules! d_Proposal_903b3a28 {
    () => {
        "\"Proposal\":{\"additionalProperties\":true,\"description\":\"A proposal for resolving a conflict the client asserts, carried on a `contradicts` relationship (HCP 4.7.4). It changes nothing until the Context Subject acts. `proposedBy` and `proposedAt` are set by the provider, never taken from a request (HCP 4.7.4).\",\"properties\":{\"act\":{\"description\":\"The act proposed (HCP 4.7.3).\",\"enum\":[\"reject\",\"accept\",\"supersede\"],\"type\":\"string\"},\"entry\":{\"description\":\"The entry the act applies to: its `ref` for a Context Client, its `id` for a Management Client (HCP 5.2.3).\",\"maxLength\":2048,\"minLength\":1,\"type\":\"string\"},\"rationale\":{\"description\":\"Why, in words the Context Subject can read (HCP 4.7.4).\",\"maxLength\":4096,\"minLength\":1,\"type\":\"string\"},\"weighed\":{\"description\":\"What the proposal considered: an open set, of which HCP defines `basis`, `declarationType`, `standing`, `permittedPurposes`, `recency` and `confidence` (HCP 4.7.4).\",\"items\":{\"maxLength\":2048,\"minLength\":1,\"type\":\"string\"},\"maxItems\":64,\"minItems\":1,\"type\":\"array\"}},\"required\":[\"act\",\"entry\",\"rationale\",\"weighed\"],\"type\":\"object\"}"
    };
}
pub(crate) use d_Proposal_903b3a28;

