macro_rules! d_PushRegistration_3670ce67 {
    () => {
        "\"PushRegistration\":{\"description\":\"A device's platform push channel — the body the device registers with its push GATEWAY (push wake-up binding, https://trusttasks.org/binding/push/0.1; modeled on Aries RFC 0699/0734). The gateway holds this token and returns an opaque WakeHandle in exchange; the token is held by the gateway ONLY, never by the mediator or the maintainer/VTA. The gateway uses it to send a contentless wake-up when an authorized trigger asks — the push payload never carries Trust Task content. Tagged union over the discriminator `platform`.\",\"oneOf\":[{\"additionalProperties\":false,\"properties\":{\"environment\":{\"description\":\"Which APNs environment issued the token. Maintainers route to the matching APNs endpoint.\",\"enum\":[\"sandbox\",\"production\"],\"type\":\"string\"},\"platform\":{\"const\":\"apns\"},\"token\":{\"description\":\"APNs device token (hex string issued by Apple Push Notification service).\",\"minLength\":1,\"type\":\"string\"},\"topic\":{\"description\":\"APNs topic — typically the app bundle identifier the gateway pushes to.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"platform\",\"token\",\"topic\"],\"title\":\"Apns\",\"type\":\"object\"},{\"additionalProperties\":false,\"properties\":{\"platform\":{\"const\":\"fcm\"},\"token\":{\"description\":\"Firebase Cloud Messaging registration token. The gateway sends a data message (not a notification message) so the app controls wake and display.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"platform\",\"token\"],\"title\":\"Fcm\",\"type\":\"object\"},{\"additionalProperties\":false,\"properties\":{\"endpoint\":{\"description\":\"RFC 8030 Web Push subscription endpoint.\",\"format\":\"uri\",\"type\":\"string\"},\"keys\":{\"additionalProperties\":false,\"description\":\"Web Push (RFC 8291) encryption keys. Note: per the push binding the payload remains contentless regardless of this encryption.\",\"properties\":{\"auth\":{\"description\":\"base64url-encoded auth secret.\",\"minLength\":1,\"type\":\"string\"},\"p256dh\":{\"description\":\"base64url-encoded P-256 ECDH public key.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"p256dh\",\"auth\"],\"type\":\"object\"},\"platform\":{\"const\":\"webpush\"}},\"required\":[\"platform\",\"endpoint\",\"keys\"],\"title\":\"WebPush\",\"type\":\"object\"}],\"title\":\"PushRegistration\"}"
    };
}
