macro_rules! d_ReadMarker_a9de650e {
    () => {
        "\"ReadMarker\":{\"additionalProperties\":false,\"description\":\"Where a member has seen one room's conversation up to: the room version they have seen it to, and the host's `createdAt` of the newest message they have seen. A reader that keeps a copy of the room counts as unread a message first stored after `version`; a reader that keeps no copy counts one whose `createdAt` (else `updatedAt`) is after `createdAt` (rooms/changed, What a reader does with a signal, step 4). Markers are ordered by `version`, then by `createdAt` (an absent `createdAt` before any present one): the greater is further on. Carries nothing about which messages, who wrote them, or when the member read them.\",\"properties\":{\"createdAt\":{\"description\":\"The host's `createdAt` of the newest message the member has seen, the member's own included — else its `updatedAt` where the host kept no `createdAt` for it — exactly as the host returned it. For a reader that keeps no copy of the room. Absent when the member has seen no message in the room. Never the author's `writtenAt`, which a writer chooses, and never when the member read it.\",\"format\":\"date-time\",\"type\":\"string\"},\"version\":{\"description\":\"The highest room version the member has seen the conversation to: every message the room held at or below this version has been shown to them. `0` means none: the member has seen nothing in the room, which is what marking a whole room unread sets. A room version as rooms/records/list returns it, never a count of messages.\",\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"version\"],\"title\":\"ReadMarker\",\"type\":\"object\"}"
    };
}
pub(crate) use d_ReadMarker_a9de650e;

macro_rules! d_ReadResult_738bb8de {
    () => {
        "\"ReadResult\":{\"additionalProperties\":false,\"description\":\"One key's answer in a batch read. Either an `error` alone beside `key`, or the record: `version` and `verification`, with the members a single read returns. Never both.\",\"properties\":{\"author\":{\"description\":\"The member who wrote it, where the tier discloses one. Absent on `private`, where authorship is inside the body the recipient just opened.\",\"type\":\"string\"},\"bodyStoredAt\":{\"description\":\"When the host stored the body this version carries, passed through from `rooms/records/get/0.3` exactly as served (`RecordMetadataV3.bodyStoredAt`). The recipient verifies the author's proof against the DID document as it stood then. Absent where the host served none.\",\"format\":\"date-time\",\"type\":\"string\"},\"cleartext\":{\"additionalProperties\":true,\"description\":\"The record body on an `open` room, where there is nothing to open. Carried as itself rather than base64url so that the shape says which tier the member is on — a member ought to be able to tell that this room's host can read what they just read.\",\"type\":\"object\"},\"createdAt\":{\"description\":\"When the host stored the record's first version, passed through from `rooms/records/get/0.3` exactly as served (`RecordMetadataV3.createdAt`). Absent where the host served none.\",\"format\":\"date-time\",\"type\":\"string\"},\"createdBy\":{\"description\":\"The author of the record's first version as the host recorded it, passed through from `rooms/records/get/0.3` exactly as served — `open` and `attributed` rooms only (`RecordMetadataV3.createdBy`). Absent where the host served none.\",\"maxLength\":2048,\"pattern\":\"^did:\",\"type\":\"string\"},\"error\":{\"$ref\":\"#/$defs/KeyError\"},\"key\":{\"type\":\"string\"},\"plaintext\":{\"description\":\"The opened record, base64url — the sealed tiers. **Never the key**, which is the whole reason this task exists rather than the record being handed to the member to open. Spelled as `rooms/keys/open` spells it, because it is the same bytes by the same route.\",\"type\":\"string\"},\"status\":{\"description\":\"Curation state, passed through. A `retracted` record has no body: the tombstone is the answer, not a failure.\",\"enum\":[\"active\",\"deprecated\",\"retracted\"],\"type\":\"string\"},\"updatedAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"verification\":{\"$ref\":\"#/$defs/ReadVerification\",\"description\":\"What the recipient checked and what it found. REQUIRED: an agent that returns a record without saying what it checked has made the member's decision for them.\"},\"version\":{\"description\":\"The record's version at the host.\",\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"key\"],\"title\":\"ReadResult\",\"type\":\"object\"}"
    };
}
pub(crate) use d_ReadResult_738bb8de;

macro_rules! d_ReadVerification_3b74557b {
    () => {
        "\"ReadVerification\":{\"additionalProperties\":false,\"description\":\"What the agent checked on the member's behalf, and what it found.\\n\\n**A verdict, never an error.** None of these values fails the task, including the ones that report a host caught out. A member's own agent refusing to hand over a record because the *host* misbehaved punishes the member for somebody else's act — and locks them out of the room holding the records that would show what happened, at the moment they most need them. The consequence belongs on the **write** path, where continuing to hand material to a party you have caught is what compounds the damage.\\n\\nSo a consumer **MUST NOT** treat any value here as a failed read, and **MUST** surface an adverse one rather than logging it. What that costs is words: a member shown a bare warning icon dismisses it, and a member later refused a write with no explanation blames their own agent. A detection the member attributes to the wrong party is worse than no detection.\\n\\nMembers are **absent where the task cannot produce them** rather than carrying a not-applicable value — a listing has no `trace` because there is no single record to trace, and a single read has no `count` because a count is only checkable against a listing read to its end.\",\"properties\":{\"anchor\":{\"description\":\"How what the host served compares with the room's own **witnessed anchor** (`EpochAnchor`).\\n\\nThis is the comparison that needs neither a gossip channel rooms deliberately lack nor durable state in an agent: every member resolves the same room DID and reads the same entry, co-signed by witnesses. It is the only one of the three a first-time reader can make.\\n\\n  - `agrees` — the host served the anchored state, and its root matches.\\n  - `ahead` — the room has moved past the anchor. The ordinary case; an anchor describes a moment, not the present, and says nothing about records written since.\\n  - `behind` — **the host is serving a state older than the room's own witnessed statement.** A rollback, and a detection nothing else in this family can make: a member with no history, no peer and no prior read still catches it.\\n  - `conflict` — same `headVersion` as the anchor, different root. The host has contradicted a value its own room published and witnesses co-signed.\\n  - `none` — the room has published no anchor. Not a fault; anchoring costs a witnessed update and a key rotation, and a room may reasonably decline.\\n  - `notChecked` — the consumer did not resolve the room. An honest answer, and **not** a synonym for `none`: one says the room published nothing, the other says nobody looked.\",\"enum\":[\"agrees\",\"ahead\",\"behind\",\"conflict\",\"none\",\"notChecked\"],\"type\":\"string\"},\"count\":{\"description\":\"Whether the number of records returned matches the `recordCount` the host committed to.\\n\\nOnly ever comparable against a listing with **no** `prefix`, **no** `sinceVersion` and read to its end — anything else legitimately holds fewer, and comparing it is a discrepancy the reader manufactured. `notComparable` is that case, and it is the common one.\\n\\n`short` is a host contradicting itself inside one exchange: it committed to a tree of N records and served fewer, with no filter to explain the difference. That is the omission the commitment exists to make detectable, caught without a second party and without an anchor.\",\"enum\":[\"agrees\",\"short\",\"notComparable\",\"notOffered\"],\"type\":\"string\"},\"head\":{\"additionalProperties\":false,\"description\":\"What the host asserted about the room, passed through unaltered so the member can compare it somewhere this agent cannot reach — with another member, or against a witnessed anchor. All three or none: a root without the state it describes is not comparable to another root, which is the whole of `HeadVersion`.\",\"properties\":{\"dataCommitment\":{\"$ref\":\"#/$defs/DataCommitment\"},\"headVersion\":{\"$ref\":\"#/$defs/HeadVersion\"},\"recordCount\":{\"$ref\":\"#/$defs/RecordCount\"}},\"required\":[\"dataCommitment\",\"recordCount\",\"headVersion\"],\"type\":\"object\"},\"priorRoots\":{\"description\":\"Whether this root matches what the agent has seen from this host for this room **at this `headVersion`**.\\n\\nThis is the comparison a member cannot make for themselves. A tab does not outlive itself and a CLI holds nothing; the agent is the only party on the member's side of the boundary that saw both reads.\\n\\n  - `agree` — seen at this head before, same root.\\n  - `conflict` — seen at this head before, **different root**. A host caught: there is no write to attribute the difference to, because a write would have moved the head.\\n  - `noneHeld` — first read at this head. Not evidence of anything; a memory of one is not a comparison.\\n  - `notChecked` — this agent keeps no root history. An honest answer for an agent that cannot make the comparison, and **not** a synonym for `noneHeld`: one says nothing was found, the other says nothing was looked for.\\n\\nREQUIRED, so that an agent which does not check has to say so rather than omit the question.\",\"enum\":[\"agree\",\"conflict\",\"noneHeld\",\"notChecked\"],\"type\":\"string\"},\"trace\":{\"description\":\"Whether the record's `RecordTrace` reached the `dataCommitment` served beside it.\\n\\n`verified` says the record is under the root the host asserted — and **nothing about whether that root is the room's**, which is what `priorRoots` and an anchor are for. `notOffered` is a host that maintains no tree, which is legal and informative. `failed` is arithmetic that does not close: the host served a path that does not reach its own root, which is either a defect or a fabrication and is not distinguishable from here.\",\"enum\":[\"verified\",\"failed\",\"notOffered\"],\"type\":\"string\"}},\"required\":[\"priorRoots\"],\"title\":\"ReadVerification\",\"type\":\"object\"}"
    };
}
pub(crate) use d_ReadVerification_3b74557b;

