macro_rules! d_RecordCount_63774d1e {
    () => {
        "\"RecordCount\":{\"description\":\"How many records the room held when `DataCommitment` was computed — the number of leaves in that tree, tombstones included, since a tombstone is a record.\\n\\n**Why a root needs this.** Certificate Transparency's signed tree head is a root *and a tree size*; this family shipped the root alone, and the half that was dropped is the half that makes a listing checkable. A reader holding a **complete, unfiltered** listing cannot recompute the root — a leaf commits to a whole record and a listing returns a projection without the body — but it can count. A host that omits a record from a listing while committing to a tree that holds it now contradicts itself in the same response, with no second party and no anchor involved.\\n\\nA host can of course understate both together. That is the point rather than a hole: the omission stops being silence and becomes a **specific claim about how many records the room holds**, which any other member's view, or any writer's signed put acknowledgement, contradicts. Making an omission attributable is the whole of what this machinery buys; it never claimed to make one impossible.\\n\\n**It counts the room, never the page.** The same rule `DataCommitment` states, and the same trap: a count scoped to what was returned is one a host satisfies by construction. So this is only comparable against a listing read to the end with **no** `prefix` and **no** `sinceVersion` — a filtered listing legitimately holds fewer, and a reader that compares one against this has found a discrepancy it created itself.\",\"minimum\":0,\"title\":\"RecordCount\",\"type\":\"integer\"}"
    };
}
pub(crate) use d_RecordCount_63774d1e;

macro_rules! d_RecordEditedAt_afbfa52f {
    () => {
        "\"RecordEditedAt\":{\"description\":\"The instant the author made the edit that produced this version, RFC 3339 in UTC (`Z`). Set by the writer of every version after the first, and absent on the first, so that a reader seeing a record for the first time can tell whether it was ever edited — which `version` cannot say, since curation moves it too. Signed with the body on the sealed tiers. A reader shows a record carrying it as edited, and treats an implausible one as `SealedRecordBody` (*Edits*) says. Governed by `RoomProfile.recordMembers` like `writtenAt`. No host enforces or reads it.\",\"format\":\"date-time\",\"pattern\":\"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\\\.[0-9]{1,9})?Z$\",\"title\":\"RecordEditedAt\",\"type\":\"string\"}"
    };
}
pub(crate) use d_RecordEditedAt_afbfa52f;

macro_rules! d_RecordEvidenceCredential_0d7cd75d {
    () => {
        "\"RecordEvidenceCredential\":{\"additionalProperties\":false,\"description\":\"Cites a credential.\",\"properties\":{\"credentialId\":{\"description\":\"The credential's `id`. An identifier: never fetched because a record names it.\",\"maxLength\":2048,\"minLength\":1,\"type\":\"string\"},\"digest\":{\"$ref\":\"#/$defs/DigestMultibase\",\"description\":\"OPTIONAL. A digest of the credential as cited — the SHA-256 multihash of its RFC 8785 (JCS) canonicalization, `proof` included — so a reader holding a credential with this `id` can tell whether it is the one the author meant.\"},\"kind\":{\"const\":\"credential\"}},\"required\":[\"kind\",\"credentialId\"],\"title\":\"RecordEvidenceCredential\",\"type\":\"object\"}"
    };
}
pub(crate) use d_RecordEvidenceCredential_0d7cd75d;

