macro_rules! d_RepoStatus_632afb1e {
    () => {
        "\"RepoStatus\":{\"additionalProperties\":false,\"description\":\"One repository as its administrators govern it: who owns it, how many hold rights on it, how far commit trust is set up, and how its forge compares with the VTC's projection.\",\"properties\":{\"bootstrap\":{\"$ref\":\"#/$defs/Bootstrap\"},\"checkedAt\":{\"description\":\"When the forge was last compared. Absent if never.\",\"format\":\"date-time\",\"type\":\"string\"},\"committers\":{\"description\":\"How many live records of `git.commit.sign` it has. Implied rights are not counted.\",\"minimum\":0,\"type\":\"integer\"},\"createdAt\":{\"description\":\"When the VTC first recorded it.\",\"format\":\"date-time\",\"type\":\"string\"},\"createdBy\":{\"$ref\":\"#/$defs/Did\",\"description\":\"Who created it through the VTC. Absent for an adopted or unmanaged repository.\"},\"driftCount\":{\"description\":\"How many drift items are outstanding. The items themselves are in `git-ns/view`.\",\"minimum\":0,\"type\":\"integer\"},\"failedStep\":{\"description\":\"The step that failed on the last create or bootstrap.\",\"maxLength\":64,\"minLength\":1,\"type\":\"string\"},\"forgeId\":{\"$ref\":\"#/$defs/ForgeId\",\"description\":\"The forge's repository id, once confirmed.\"},\"guard\":{\"description\":\"The guard in force against a pull request satisfying its own check, as the bridge last reported it: `requiredWorkflow`, `codeOwnerReview`, `bridgePostedCheck`, `protectedFiles` or `none`. A client treats any other value as `none`.\",\"maxLength\":64,\"minLength\":1,\"type\":\"string\"},\"id\":{\"description\":\"The VTC's identifier for the repository record.\",\"maxLength\":128,\"minLength\":1,\"type\":\"string\"},\"lastCheck\":{\"$ref\":\"#/$defs/LastCheck\"},\"lastError\":{\"description\":\"What the bridge said when that step failed.\",\"maxLength\":4096,\"minLength\":1,\"type\":\"string\"},\"maintainers\":{\"description\":\"How many live records of `git.repo.maintain` it has. Implied rights are not counted.\",\"minimum\":0,\"type\":\"integer\"},\"namespace\":{\"$ref\":\"#/$defs/NamespaceId\",\"description\":\"The namespace it was recorded in. For a `detached` repository, possibly one no longer bound.\"},\"owners\":{\"description\":\"The DIDs holding a live, explicitly recorded `git.repo.own` on it.\",\"items\":{\"$ref\":\"#/$defs/Did\"},\"type\":\"array\",\"uniqueItems\":true},\"resource\":{\"$ref\":\"#/$defs/RepoResource\"},\"roleMap\":{\"$ref\":\"#/$defs/RoleMap\",\"description\":\"The forge role each right projects to on this repository under the serving bridge's reported map. Absent while the namespace's map is unknown.\"},\"roleMapStale\":{\"description\":\"The bridge last projected this repository's roles under an earlier role map, and the re-projection queued for it has not yet succeeded.\",\"type\":\"boolean\"},\"state\":{\"description\":\"As `RepoSummary.state` in the shared schema.\",\"enum\":[\"pendingCreate\",\"active\",\"archived\",\"detached\",\"orphaned\",\"unmanaged\"],\"type\":\"string\"},\"steps\":{\"description\":\"Per-step outcomes of the last create, bootstrap or inspect job. Empty until one has been reported.\",\"items\":{\"$ref\":\"#/$defs/StepOutcome\"},\"maxItems\":64,\"type\":\"array\"},\"syncState\":{\"description\":\"As `Sync.state` in the shared schema.\",\"enum\":[\"inSync\",\"drift\",\"pending\",\"unchecked\"],\"type\":\"string\"},\"visibility\":{\"$ref\":\"#/$defs/RepoVisibility\"}},\"required\":[\"id\",\"namespace\",\"resource\",\"visibility\",\"state\",\"owners\",\"maintainers\",\"committers\",\"bootstrap\",\"syncState\",\"driftCount\",\"createdAt\",\"steps\",\"roleMapStale\"],\"title\":\"RepoStatus\",\"type\":\"object\"}"
    };
}
pub(crate) use d_RepoStatus_632afb1e;

macro_rules! d_RepoSummary_25340089 {
    () => {
        "\"RepoSummary\":{\"additionalProperties\":false,\"description\":\"One repository as the VTC records it.\",\"properties\":{\"bootstrap\":{\"$ref\":\"#/$defs/Bootstrap\"},\"forgeId\":{\"$ref\":\"#/$defs/ForgeId\",\"description\":\"The forge's repository id. Absent until the forge has confirmed the repository exists (a `pendingCreate` repository, or one adopted in bridge mode before the first inspection).\"},\"owners\":{\"description\":\"The DIDs holding `git.repo.own` on this repository by an explicit grant. Empty only for an `unmanaged` repository, and for an `orphaned` one whose ownership rests with the namespace admins by implication.\",\"items\":{\"$ref\":\"#/$defs/Did\"},\"type\":\"array\",\"uniqueItems\":true},\"resource\":{\"$ref\":\"#/$defs/RepoResource\"},\"state\":{\"description\":\"`pendingCreate` — the name is reserved and the repository is not yet confirmed on the forge. `active` — managed. `archived` — archived through git-ns/repo/archive; commit rights on it are revoked. `detached` — no longer governed: its namespace was unbound, or it moved outside the namespace. `orphaned` — its last owner left the community and ownership passed to the namespace admins, who have not yet named a new owner. `unmanaged` — it exists on the forge inside a bound namespace but was never created or adopted through the VTC.\",\"enum\":[\"pendingCreate\",\"active\",\"archived\",\"detached\",\"orphaned\",\"unmanaged\"],\"type\":\"string\"},\"sync\":{\"$ref\":\"#/$defs/Sync\"},\"visibility\":{\"$ref\":\"#/$defs/RepoVisibility\"}},\"required\":[\"resource\",\"visibility\",\"state\",\"owners\",\"bootstrap\",\"sync\"],\"title\":\"RepoSummary\",\"type\":\"object\"}"
    };
}
