macro_rules! d_Response_75e7391f {
    () => {
        "\"Response\":{\"$anchor\":\"response\",\"additionalProperties\":false,\"dependentRequired\":{\"headVersion\":[\"dataCommitment\"],\"recordCount\":[\"dataCommitment\"],\"trace\":[\"dataCommitment\",\"status\",\"updatedAt\"]},\"description\":\"Success response to rooms/records/get. Type https://trusttasks.org/spec/rooms/records/get/0.3#response.\",\"properties\":{\"author\":{\"description\":\"The member who wrote it. Present on `open` and `attributed`, absent on `private` where the author is sealed with the body. Committed. Mirrors `CommittedRecord`, which fixes the leaf preimage; see the note on `trace`.\\n\\nThis member is new to this response and is a **disclosure**: `rooms/records/list` already returns it on those tiers, so it tells a reader nothing the family withheld, but a host serving a single record now names its writer where before it did not. It is not conditional on `trace` — a reader wanting the record without the writer's identifier is asking for a different room tier, not a different response.\",\"type\":\"string\"},\"blobs\":{\"description\":\"The stored blobs this record names, exactly as rooms/records/put (0.2 and later) wrote them: the file's ciphertext, fetched with rooms/blobs/get. Absent when the record names none, when it is retracted, and on records written by put 0.1. Cleartext on every tier, as on the write. NOT committed: CommittedRecord predates it, so a reader removes it, with the verification members and `ext`, before hashing the leaf (see `trace`).\",\"items\":{\"$ref\":\"#/$defs/BlobRef\"},\"maxItems\":1,\"minItems\":1,\"type\":\"array\",\"uniqueItems\":true},\"bodyStoredAt\":{\"description\":\"When the host stored the body this version carries, unchanged by curation (`RecordMetadataV3.bodyStoredAt`). Every tier; absent for a version stored before the host kept it. NOT committed: removed before hashing the leaf, like `createdAt`.\",\"format\":\"date-time\",\"type\":\"string\"},\"cleartext\":{\"additionalProperties\":true,\"description\":\"Present on an `open` room.\",\"type\":\"object\"},\"createdAt\":{\"description\":\"When the host stored the record's first version, unchanged by every later version and every curation (`RecordMetadataV3.createdAt`). Every tier; absent for a record stored before the host kept it. NOT committed: a reader removes it, with `blobs`, the verification members and `ext`, before hashing the leaf (see `trace`).\",\"format\":\"date-time\",\"type\":\"string\"},\"createdBy\":{\"description\":\"The author of the record's first version, as the host recorded it (`RecordMetadataV3.createdBy`). Present on `open` and `attributed` only, never on `private`; absent for a record stored before the host kept it. NOT committed: removed before hashing the leaf, like `createdAt`.\",\"maxLength\":2048,\"pattern\":\"^did:\",\"type\":\"string\"},\"dataCommitment\":{\"$ref\":\"#/$defs/DataCommitment\",\"description\":\"The room's data commitment at the moment this record was read. Carried on a single-record read as well as a listing so a reader can tell whether the room moved between two reads — and so a `trace` returned beside it has a root to reach.\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"headVersion\":{\"$ref\":\"#/$defs/HeadVersion\",\"description\":\"The room's highest assigned record version, as of `dataCommitment`. Present only beside `dataCommitment`, and computed from the same snapshot: it describes the state that root was taken over, and a head that does not belong to that root is worse than none. Without it two roots are not comparable at all: a host shown to have served two different ones answers that the room moved, and nothing contradicts it.\"},\"key\":{\"type\":\"string\"},\"pinned\":{\"const\":true,\"description\":\"Present **only** when the record is pinned; absent means it is not. Committed. Mirrors `CommittedRecord`, which fixes the leaf preimage; see the note on `trace`. `false` is not a permitted spelling: absent is how false is written in the preimage, and two spellings would give one record two roots.\",\"type\":\"boolean\"},\"recordCount\":{\"$ref\":\"#/$defs/RecordCount\",\"description\":\"How many records the room holds, as of `dataCommitment`. Present only beside `dataCommitment`, and computed from the same snapshot: it describes the state that root was taken over, and a head that does not belong to that root is worse than none.\"},\"sealed\":{\"$ref\":\"#/$defs/SealedRecord\",\"description\":\"Present on an `attributed` or `private` room.\"},\"status\":{\"description\":\"Curation state. Committed. Mirrors `CommittedRecord`, which fixes the leaf preimage; see the note on `trace`. A host that serves a `trace` MUST serve this, because a reader cannot reach the leaf without it — and a host that could omit it could retract a record without touching a byte of it.\",\"enum\":[\"active\",\"deprecated\",\"retracted\"],\"type\":\"string\"},\"trace\":{\"$ref\":\"#/$defs/RecordTrace\",\"description\":\"The path from this record's leaf to `dataCommitment`, proving the record sits under the root the host just asserted.\\n\\n**The leaf preimage is this response payload with its verification members — `dataCommitment`, `recordCount`, `headVersion` and `trace` — `ext` and `blobs` removed** — which is exactly `CommittedRecord`, and a reader MAY validate the object it assembles against that definition before hashing it. Nothing is reconstructed and no member is carried twice; the reader deletes members from what it already holds.\\n\\nOPTIONAL, on the same reasoning as `dataCommitment`: a host that maintains no tree must not invent one. A host that serves this MUST have computed it and `dataCommitment` from the same snapshot, and MUST serve every committed member it holds — an omitted `status`, `updatedAt`, `pinned` or `author` yields a leaf the reader cannot reach, so the failure is a refused trace rather than a false one.\"},\"updatedAt\":{\"description\":\"RFC 3339. Committed. Mirrors `CommittedRecord`, which fixes the leaf preimage; see the note on `trace`. Required alongside a `trace` for the same reason `status` is.\",\"format\":\"date-time\",\"type\":\"string\"},\"version\":{\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"key\",\"version\"],\"title\":\"Rooms Records Get — response payload\",\"type\":\"object\"}"
    };
}
