macro_rules! d_RetentionPolicy_3edd7373 {
    () => {
        "\"RetentionPolicy\":{\"$comment\":\"Deliberately no JSON Schema `default`. A declared default is materialised by the generated bindings — the member becomes non-optional with a serde default — so an absent value would reappear as an explicit one on re-serialisation and break round-trip idempotence for every document written before this member existed. The meaning of absence is stated in prose, where a binding cannot act on it.\",\"description\":\"Whether a room keeps its history readable across a membership change, fixed at creation and immutable thereafter — like `Visibility`, and for the same reason: the rungs of an epoch key chain either exist for an epoch or they do not, and no later change of mind can seal key material that was never sealed or unseal what was already severed. `chained`: each advance produces an `EpochLink`, so every member reads the room's whole retained history however long they have been in it — what a **library** wants, at the cost of post-compromise security for record content, since a compromised current key then reaches every retained epoch. `fromJoin`: no rungs are produced, so a member reads only from the epoch their group state is at — what a **stream** wants, and what a room under a strict forward-secrecy obligation wants, at the cost that a joining member finds an empty-looking room and nobody can reread a record once their group state has moved past the epoch it was sealed under. Absent means `chained`; see the prose on why the absent case is the readable one.\",\"enum\":[\"chained\",\"fromJoin\"],\"title\":\"RetentionPolicy\",\"type\":\"string\"}"
    };
}
pub(crate) use d_RetentionPolicy_3edd7373;

macro_rules! d_RevocationEntry_60145b1a {
    () => {
        "\"RevocationEntry\":{\"description\":\"One withdrawal in a `RevocationList`, discriminated by `kind`.\\n\\n  - `credential` withdraws one credential, named by its `id`. It matches the membership credential or any authority link whose `id` equals `credentialId`.\\n  - `subject` withdraws a party: every credential the room's chain gave them **before** `revokedAt`. It matches the membership credential or any authority link whose `credentialSubject` id **or** `issuer` is `subject` and whose `validFrom` is earlier than `revokedAt`. Matching the issuer as well as the subject withdraws what the party delegated before their removal, which no re-admission revives. A credential carrying no `validFrom` is treated as issued before every entry.\\n  - `room` withdraws every credential whose `validFrom` is earlier than `revokedAt`, whoever holds it. It is how a room resets access — after a compromise, or on a `private` room, where naming a party would disclose who was a member.\\n\\n**Keyed on time, so a party can come back.** A `subject` or `room` entry withdraws what was issued before it and nothing after, so a room that re-admits a removed party issues fresh credentials and they verify. A `credential` entry is permanent for that one credential, which nobody re-issues.\\n\\n**Tiers.** On a `private` room a host MUST refuse a list carrying a `credential` or `subject` entry: a presentation there withholds the credential and its subject, so such an entry is one the host cannot apply and a disclosure of who was in the room. Only `room` entries are permitted, and a host serving a `private` room MUST refuse any presentation for which it cannot establish that no credential in it has a `validFrom` earlier than the latest `room` entry's `revokedAt`.\",\"oneOf\":[{\"$ref\":\"#/$defs/CredentialRevocation\"},{\"$ref\":\"#/$defs/SubjectRevocation\"},{\"$ref\":\"#/$defs/RoomRevocation\"}],\"title\":\"RevocationEntry\"}"
    };
}
pub(crate) use d_RevocationEntry_60145b1a;

macro_rules! d_RevocationHead_344c9506 {
    () => {
        "\"RevocationHead\":{\"additionalProperties\":false,\"description\":\"Which `RevocationList` a party holds, without its entries: comparable between the room's key holder and a host, and between two hosts, without disclosing whom the room withdrew.\",\"properties\":{\"digest\":{\"$ref\":\"#/$defs/DigestMultibase\",\"description\":\"SHA-256 multihash of the list's RFC 8785 (JCS) canonicalization, `proof` included. Two parties holding one sequence with different digests have been given two lists the room signed at one sequence.\"},\"sequence\":{\"description\":\"The list's `sequence`.\",\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"sequence\",\"digest\"],\"title\":\"RevocationHead\",\"type\":\"object\"}"
    };
}
pub(crate) use d_RevocationHead_344c9506;

macro_rules! d_RevocationList_4edf7ac6 {
    () => {
        "\"RevocationList\":{\"additionalProperties\":false,\"description\":\"The room's own statement of which credentials it has withdrawn before they expire — signed by the room, cumulative, and numbered, so that it means the same thing at every host it is delivered to.\\n\\n**Why the room signs it, and why it is cumulative.** A host authorizes from credentials the room issued and keeps no roster; a withdrawal kept only as a host's own state would make the room unmovable and the host part of the membership. A list the room signed is room state: it moves with the room, any host it is delivered to reaches the same decision, and nothing a host invents can be mistaken for it. It is cumulative — every list carries every entry still in force — so a host holding any one list holds the room's whole withdrawal state, and a host that missed a list loses nothing once it receives a later one.\\n\\n**Producing.** The room's key holder builds the object without `proof` and signs it with a W3C Data Integrity proof whose `verificationMethod` is a key the room's DID document lists for `assertionMethod` and whose `proofPurpose` is `assertionMethod`. A producer MUST support `eddsa-jcs-2022`. Each list's `sequence` is exactly one greater than the last list the room signed, and the producer MUST NOT sign two different lists at one `sequence`.\\n\\n**Accepting.** A host MUST refuse a list unless: (1) `roomId` is the room it is delivered for; (2) `proof` verifies with a key of `roomId` listed for `assertionMethod` — a list signed by any other key, however valid the signature, is not the room's; (3) `sequence` is greater than that of the list it holds, or equal with an identical list (a repeat, answered as accepted and changing nothing); (4) it is **append-only** against the list it holds: every entry of the held list appears in it unchanged, unless that entry's `until` has passed. A list that lowers the sequence is a rollback and one that drops a live entry is a reinstatement nobody signed for, and both are refused; two different lists at one `sequence` is the room's key equivocating, and the host keeps the list it holds.\\n\\n**Applying.** A credential is revoked by an accepted list when any entry matches it (see `RevocationEntry`). An entry whose `until` has passed MAY be discarded by a host and omitted from later lists; no other entry is ever dropped.\\n\\n**Size.** A list is bounded at 4096 entries. A room that would exceed it uses a `room` entry, which withdraws everything issued before it and lets the room re-issue to those who remain.\",\"properties\":{\"entries\":{\"description\":\"Every withdrawal still in force, in the order the room made them. Empty is valid: a room that has revoked nothing, or whose every entry has lapsed, can still state its sequence.\",\"items\":{\"$ref\":\"#/$defs/RevocationEntry\"},\"maxItems\":4096,\"type\":\"array\"},\"issuedAt\":{\"description\":\"When the room signed this list.\",\"format\":\"date-time\",\"type\":\"string\"},\"proof\":{\"description\":\"The room's Data Integrity proof over every other member, made with a key the room's DID document lists for `assertionMethod`.\",\"type\":\"object\"},\"roomId\":{\"description\":\"The room whose credentials this list withdraws, exactly as on the wire. Signed, so a list cannot be replayed against another room.\",\"maxLength\":512,\"minLength\":1,\"type\":\"string\"},\"sequence\":{\"description\":\"The list's position in the room's sequence: exactly one greater than the last list the room signed. A host accepts only a list whose sequence is above the one it holds, which is what stops a host, a relayer or an attacker holding an old list from rolling the room's withdrawals back.\",\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"roomId\",\"sequence\",\"issuedAt\",\"entries\",\"proof\"],\"title\":\"RevocationList\",\"type\":\"object\"}"
    };
}
pub(crate) use d_RevocationList_4edf7ac6;

