macro_rules! d_RollRule_2365525e {
    () => {
        "\"RollRule\":{\"additionalProperties\":false,\"dependentSchemas\":{\"memberOf\":{\"not\":{\"required\":[\"listed\"]},\"properties\":{\"rule\":{\"const\":\"credential\"}}},\"rule\":{\"anyOf\":[{\"required\":[\"memberOf\"]},{\"properties\":{\"rule\":{\"enum\":[\"members\",\"membersAndListed\",\"listed\"]}}}]}},\"description\":\"Who may be issued a ticket (VTI-VOT-021): the community's active members (`members`), its active members and the parties `listed` names (`membersAndListed`), only the parties `listed` names (`listed`), or the holders of a membership credential for the one DID `memberOf` names (`credential`), proven by presentation when the holder claims their ticket and never resolved when the election is created (VTI-VOT-025). `memberOf` is present exactly when `rule` is `credential`, and `listed` is never present with it.\",\"properties\":{\"listed\":{\"items\":{\"description\":\"A DID enfranchised by name.\",\"maxLength\":2048,\"minLength\":1,\"type\":\"string\"},\"type\":\"array\",\"uniqueItems\":true},\"memberOf\":{\"description\":\"The DID whose membership credential admits its holder, under the `credential` rule: this community, one of its groups, or a party that is itself an active member of this community — holding a membership credential this community issued it — such as another community, a group of another community, or a network (VTI-VOT-026). Always a DID, never a group's local identifier or name. A community refuses to create an election naming any other DID (vtc/elections/create:rollUntrusted).\",\"maxLength\":2048,\"minLength\":8,\"pattern\":\"^did:[a-z0-9]+:\\\\S+$\",\"type\":\"string\"},\"rule\":{\"enum\":[\"members\",\"membersAndListed\",\"listed\",\"credential\"],\"type\":\"string\"}},\"required\":[\"rule\"],\"title\":\"RollRule\",\"type\":\"object\"}"
    };
}
