macro_rules! d_SigningKey_d5629f1c {
    () => {
        "\"SigningKey\":{\"additionalProperties\":false,\"description\":\"One signing-key delegation, as its holder sees it. A delegation confers nothing of its own: it names an identity that already holds whatever standing it holds, and a document signed by the key is authorized by that identity's standing read at execution time.\",\"properties\":{\"active\":{\"description\":\"Whether the delegation authorizes documents right now: not revoked and not past `expiresAt`. Computed by the consumer with the predicate its verifier applies, so a holder does not re-implement it and disagree.\",\"type\":\"boolean\"},\"createdAt\":{\"description\":\"When the delegation was enrolled.\",\"format\":\"date-time\",\"type\":\"string\"},\"deviceLabel\":{\"$ref\":\"#/$defs/DeviceLabel\"},\"expiresAt\":{\"description\":\"When the delegation stops authorizing documents. Always present: the consumer sets it at enrolment and caps it at its own maximum lifetime, whatever the producer asked for, so no delegation outlives the consumer's policy.\",\"format\":\"date-time\",\"type\":\"string\"},\"identityDid\":{\"description\":\"The identity the key acts for. Included so a holder need not infer it.\",\"maxLength\":2048,\"minLength\":5,\"pattern\":\"^did:\",\"type\":\"string\"},\"lastUsedAt\":{\"description\":\"When the delegation last authorized a document, as far as the consumer recorded. A usability signal for choosing which key to revoke, recorded best-effort; its absence does not mean the key was never used.\",\"format\":\"date-time\",\"type\":\"string\"},\"revokedAt\":{\"description\":\"When the delegation was revoked. A revoked delegation authorizes nothing and its key cannot be enrolled again.\",\"format\":\"date-time\",\"type\":\"string\"},\"scope\":{\"$ref\":\"#/$defs/SigningKeyScope\"},\"signingKeyDid\":{\"$ref\":\"#/$defs/SigningKeyDid\"}},\"required\":[\"signingKeyDid\",\"identityDid\",\"scope\",\"createdAt\",\"expiresAt\",\"active\"],\"title\":\"SigningKey\",\"type\":\"object\"}"
    };
}
pub(crate) use d_SigningKey_d5629f1c;

