macro_rules! d_Slot_1664d731 {
    () => {
        "\"Slot\":{\"description\":\"A role a profile entry plays within its profile, so a consumer can find it without guessing from its claim type. A profile MAY hold several entries of one type — a legal name and a display name, two phone numbers — and only a slot says which answers a given question. Unique within a profile.\\n\\nWell-known slots:\\n\\n- `displayName` — what this face calls itself. The entry a consumer renders as the face's name to anyone it is shown to. Distinct from the profile's own `name`, which is the holder's private label and never disclosed.\\n- `primaryEmail`, `primaryPhone`, `primaryAddress` — the entry to use where a counterparty asks for one of a kind and the profile holds several.\\n- `avatar` — the image this face presents.\\n\\nOther values are the holder's or the producer's own and carry no meaning a maintainer interprets.\",\"pattern\":\"^[a-z][A-Za-z0-9]{0,31}$\",\"title\":\"Slot\",\"type\":\"string\"}"
    };
}
