macro_rules! d_UnsignedRoomRequest_97afa9fb {
    () => {
        "\"UnsignedRoomRequest\":{\"$anchor\":\"unsigned-room-request\",\"additionalProperties\":false,\"description\":\"A Trust Task document of a type in the rooms/keys/act table, built by the member's client: no proof, and no presentation in its payload. The recipient validates the payload against the named type's own schema; this one fixes only the envelope.\",\"not\":{\"required\":[\"proof\"]},\"properties\":{\"expiresAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"id\":{\"description\":\"The request's identifier, set by the client. The host keys duplicate-execution protection on it.\",\"maxLength\":512,\"minLength\":1,\"type\":\"string\"},\"issuedAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"issuer\":{\"description\":\"The member to act as, and this task's subject (subjectPath /document/issuer). REQUIRED for a type that names no room (rooms/blobs/chunk/0.1, rooms/blobs/upload/{commit,abort}/0.2), where it is the member whose request opened the transfer; REQUIRED for the community types (vtc/rooms/offers/list/0.1, 0.2, 0.3 and 0.4, vtc/rooms/offers/accept/0.1, vtc/rooms/memberships/list/0.1 and 0.2), where it is the DID the community addressed its offers to; REQUIRED where the caller may act as more than one member of the room; optional where it may act as exactly one. A rule over two members this schema does not express: the recipient refuses an absent issuer it needs with principalAmbiguous. Never the client's own identifier.\",\"maxLength\":2048,\"pattern\":\"^did:\",\"type\":\"string\"},\"payload\":{\"description\":\"The request's payload, as the named type's schema defines it but without `presentation`: the recipient inserts the member's own, narrowed to the table's action, where the type takes one, and refuses a payload that already carries one. For vtc/rooms/offers/accept/0.1 a `keyPackage`, where present, MUST be one the recipient minted with rooms/keys/key-package at 0.1 or 0.2 (Recipient item 10).\",\"type\":\"object\"},\"recipient\":{\"description\":\"The room's host, or for the community types the community that made the offers: the party the completed document is for. Covered by the member's proof.\",\"maxLength\":2048,\"pattern\":\"^did:\",\"type\":\"string\"},\"threadId\":{\"maxLength\":512,\"minLength\":1,\"type\":\"string\"},\"type\":{\"description\":\"The room request's Type URI: a rooms/* request, or one of the community types: vtc/rooms/offers/{list,accept} or vtc/rooms/memberships/list. Only the types in this task's table are completed; any other is `typeNotActable`.\",\"maxLength\":2048,\"pattern\":\"^https://trusttasks\\\\.org/spec/(rooms|vtc/rooms/(offers|memberships))/\",\"type\":\"string\"}},\"required\":[\"id\",\"type\",\"recipient\",\"issuedAt\",\"payload\"],\"title\":\"Unsigned room request\",\"type\":\"object\"}"
    };
}
