macro_rules! d_VaultEntry_930b40e7 {
    () => {
        "\"VaultEntry\":{\"additionalProperties\":false,\"properties\":{\"archivedAt\":{\"description\":\"When the entry was archived. Present iff `status` is `archived`.\",\"format\":\"date-time\",\"type\":\"string\"},\"attachments\":{\"description\":\"References to encrypted blobs associated with the entry (recovery codes, PEM files, screenshots of authenticator setup). The blobs themselves are fetched via a separate mechanism the maintainer documents; metadata view exposes only the descriptor.\",\"items\":{\"$ref\":\"#/$defs/AttachmentRef\"},\"type\":\"array\"},\"breachedAt\":{\"description\":\"Set by the maintainer (via HIBP integration or equivalent) when the password material associated with this entry is known to appear in a public breach. Consumers SHOULD surface this prominently. Cleared when the user rotates the password and the new password is not in any known breach.\",\"format\":\"date-time\",\"type\":\"string\"},\"contextId\":{\"description\":\"Identifier of the trust context (persona) the entry belongs to. Opaque string interpreted by the vault maintainer; corresponds to a single ContextRecord on the VTA side.\",\"minLength\":1,\"type\":\"string\"},\"createdAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"createdBy\":{\"description\":\"VID of the consumer that originally created the entry.\",\"type\":\"string\"},\"customFieldNames\":{\"description\":\"Names of additional fields the user has attached (e.g. [\\\"security-question-1\\\", \\\"account-number\\\"]). The VALUES live in the secret payload and are only delivered by vault/release/0.1. Exposing names in metadata lets the consumer render the right form layout before requesting release.\",\"items\":{\"maxLength\":128,\"minLength\":1,\"type\":\"string\"},\"type\":\"array\",\"uniqueItems\":true},\"deletedAt\":{\"description\":\"When the entry was soft-deleted. Present iff `status` is `deleted`. A soft delete is reversible: this records when the grace window opened, not when the entry ceased to exist.\",\"format\":\"date-time\",\"type\":\"string\"},\"expiresAt\":{\"description\":\"Optional time after which the credential is no longer expected to be valid (e.g. an OAuth refresh token's known expiry, a time-limited API token, an enterprise password rotation policy). Maintainers MAY surface this in the consumer UI as a warning.\",\"format\":\"date-time\",\"type\":\"string\"},\"ext\":{\"$ref\":\"#/$defs/Ext\",\"description\":\"Ecosystem-defined extension members per SPEC.md §4.5.1. Reverse-DNS-namespaced; consumers MUST ignore unrecognized namespaces.\"},\"favicon\":{\"description\":\"Optional URI of an icon to display in the consumer UI. Maintainers MAY fetch and cache; consumers SHOULD treat as untrusted content and fetch via a sandboxed pipeline.\",\"format\":\"uri\",\"type\":\"string\"},\"graceUntil\":{\"description\":\"Deadline after which a `deleted` entry is irreversibly purged. Present iff `status` is `deleted`. It is the one member a consumer showing a trash view actually needs — \\\"deleted\\\" without a deadline cannot be distinguished from \\\"gone\\\", and the difference is whether the holder can still get their credential back.\",\"format\":\"date-time\",\"type\":\"string\"},\"id\":{\"description\":\"Opaque vault-maintainer-assigned identifier for the entry. ULID/UUID/base32 are common; the wire spec only requires non-empty string equality.\",\"minLength\":1,\"type\":\"string\"},\"label\":{\"description\":\"Human-readable display name (e.g. \\\"Work GitHub\\\", \\\"Personal bank — checking\\\"). Bounded on the wire at 256 characters; a maintainer MAY enforce a shorter limit.\",\"maxLength\":256,\"minLength\":1,\"type\":\"string\"},\"lastUsedAt\":{\"description\":\"Most recent time the entry was used (either released or proxy-login performed). Maintainers MAY return this with reduced precision (e.g. hour-floored) when releasing to a less-trusted consumer.\",\"format\":\"date-time\",\"type\":\"string\"},\"notes\":{\"description\":\"Non-sensitive notes the user attached to the entry. Visible in metadata view (suitable for support contact, account number, expiry policy memos). SENSITIVE notes belong in the secret payload as a `secureNotes` field — those are only released by vault/release/0.1.\",\"maxLength\":4096,\"type\":\"string\"},\"passwordChangedAt\":{\"description\":\"Set whenever the password component of the secret payload is rotated. Maintainers MUST update this on every secret-material change for entries of kind `password` (or any kind that carries a password component). Used by consumers to surface rotation-overdue warnings.\",\"format\":\"date-time\",\"type\":\"string\"},\"principalDid\":{\"description\":\"Optional cached DID the entry will act AS for DID-shaped flows — mirrors the `did` field of the entry's secret payload when `secretKind` carries one (`did-self-issued`, `didcomm-peer`). Absent for kinds that have no DID concept (`password`, `passkey`, `oauth-tokens`, `bearer-token`, `ssh-key`, `custom`). MAINTAINER-DERIVED, NOT CONSUMER-SUPPLIED: the maintainer MUST recompute this from the canonical secret at every upsert / secret rotation; a producer-supplied value on `vault/upsert/0.1` MUST be ignored (no error, but no honour). Read-only on the wire, present in metadata views so consumers can drive RP-side flows (e.g. fetch `/auth/challenge` keyed on the principal DID before requesting a proxy-login) without releasing the secret.\",\"minLength\":1,\"type\":\"string\"},\"secretKind\":{\"$ref\":\"#/$defs/SecretKind\",\"description\":\"Discriminator for the kind of secret this entry holds. The secret material itself is NEVER returned in metadata views; the kind is exposed so consumers can render an appropriate UI affordance and so policy decisions can route by kind.\"},\"selectors\":{\"description\":\"Opaque maintainer-defined selector strings fed to the policy engine when this entry is requested (e.g. \\\"recent_uv_required\\\", \\\"network_class=corp\\\", \\\"step_up_push\\\"). Consumers MUST treat selectors as opaque; they exist for policy authoring on the maintainer side.\",\"items\":{\"minLength\":1,\"type\":\"string\"},\"type\":\"array\",\"uniqueItems\":true},\"status\":{\"description\":\"Archival-lifecycle state of this entry. Absent means `active`, so a maintainer that models no lifecycle omits it and every existing document stays valid. Deliberately carries no JSON Schema `default`: a declared default is materialised by generated bindings, which would make an absent `status` reappear as an explicit `\\\"active\\\"` on re-serialisation and break round-trip idempotence for every existing document. This member is what makes `vault/list`'s `status: \\\"all\\\"` selector usable: that view returns entries in every state by design, and without a state on the entry itself a consumer cannot tell which is which. An `archived` entry is hidden from ordinary listings but intact; a `deleted` entry is a tombstone inside its grace window, still restorable until `graceUntil` passes.\",\"enum\":[\"active\",\"archived\",\"deleted\"],\"type\":\"string\"},\"tags\":{\"description\":\"User-defined tags for organisation and filtering (e.g. [\\\"family\\\", \\\"finance\\\"]). Maintainers MAY enforce a maximum count; the wire spec does not.\",\"items\":{\"maxLength\":64,\"minLength\":1,\"type\":\"string\"},\"type\":\"array\",\"uniqueItems\":true},\"targets\":{\"description\":\"One or more binding targets — web origins, mobile app identifiers, and/or DIDs — that this credential applies to. A request from any matching target uses this entry. A typical entry for a service that exists as both a website and mobile apps will list a web origin, an iOS bundle id, and an Android package id; passkeys for that service typically list only the origin (because iOS Associated Domains and Android Asset Links bind apps to the domain at the OS level).\",\"items\":{\"$ref\":\"#/$defs/SiteTarget\"},\"minItems\":1,\"type\":\"array\"},\"updatedAt\":{\"format\":\"date-time\",\"type\":\"string\"},\"updatedBy\":{\"description\":\"VID of the consumer that last modified the entry.\",\"type\":\"string\"},\"version\":{\"description\":\"Monotonic version counter incremented on every mutation. Used by consumers for optimistic-concurrency checks on vault/upsert and as the seq baseline for vault/sync.\",\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"id\",\"contextId\",\"targets\",\"label\",\"secretKind\",\"createdAt\",\"updatedAt\",\"version\"],\"title\":\"VaultEntry\",\"type\":\"object\"}"
    };
}
pub(crate) use d_VaultEntry_930b40e7;

